const ROLE_SUMMARY_OVERRIDES = {
  'Grave Robber': 'Nhận một mục tiêu đầu ván. Khi họ bị loại, bạn nhận vai của họ vào đầu ngày kế tiếp.',

  'Blight': 'Gieo bệnh qua đêm và chọn thời điểm loại người đã nhiễm.',
  'Deep Sea Terror': 'Đánh dấu người chơi để khóa phiếu, rồi có thể loại cả nhóm.',
  'Little Girl': 'Có thể hé mắt nhìn lén khi bầy Sói chọn nạn nhân.',
  'Grumpy Grandma': 'Từ đêm 2, chọn một người bị cấm nói và bỏ phiếu trong ngày sau.',
  'Watchdog': 'Cử hai chó canh để chặn đòn Sói và Sát nhân.',
  'Wolf Time Traveler': 'Một lần tua ván về đầu ngày trước, từ đêm 3.',
  'Dorothy': 'Ghé thăm các vai khác để mở lượt tạt nước.'
};

function roleSummary(role) {
  return ROLE_SUMMARY_OVERRIDES[role.english] || role.desc;
}

function rolePlayGuide(role) {
  if (role.random) return '';
  const detailedSteps = ROLE_PLAY_GUIDES[role.english] || [];
  const steps = detailedSteps.some(([title]) => title === 'Ví dụ')
    ? detailedSteps
    : [...detailedSteps, ['Ví dụ tại bàn', ROLE_EXAMPLES[role.english]]];
  return `<section class="role-play-guide" aria-label="Cách chơi chi tiết">
    <h3>Cách chơi chi tiết</h3>
    ${steps.map(([heading, body]) => `<p><strong>${esc(heading)}</strong><br>${esc(body)}</p>`).join('')}
  </section>`;
}

function showDealtRoleInfo() {
  const game = state.game;
  if (page !== 'game' || game?.stage !== 'deal' || !secret) return;
  const player = game.players[game.dealIndex];
  if (player) showRoleInfo(player.role, true);
}

function showRoleInfo(k,readOnly=false){const r=ROLES[k];modal.innerHTML=`<div class="dialog-head"><h2>${r.name}</h2><button class="close" data-action="close" aria-label="Đóng">×</button></div>${roleArtwork(k, true)}<p class="english-name">${r.english} · ${r.team}</p><span class="engine-badge ${r.engine}">${roleBadge(k)}</span><p class="role-description">${r.desc}</p>${rolePlayGuide(r)}${r.engine!=='auto'?'<p class="assist-note">Quản trò xử lý kỹ năng và ghi kết quả trên bảng điều khiển.</p>':''}${r.experimental&&!r.houseRule?'<p class="hint">Vai đặc biệt / thử nghiệm trong danh mục. Thống nhất luật với cả nhóm trước ván.</p>':''}${r.houseRule&&!readOnly?`<label class="field"><span>Luật nhóm áp dụng (bắt buộc)</span><textarea data-house-rule="${k}" maxlength="1500" rows="4" placeholder="Ghi rõ điều kiện kích hoạt, số lượt và cách xử lý…">${esc(state.houseRules[k]||'')}</textarea></label>`:''}${r.random?`<p class="hint">Danh sách có ${randomPool(k).length} vai có thể rút. Khi chia bài, máy thay ô này bằng một vai trong danh sách và kiểm tra giới hạn số bản sao của từng vai. Người chơi chỉ thấy vai thực tế đã rút.</p><details><summary>Danh sách vai có thể rút</summary><p>${randomPool(k).map(id=>esc(ROLES[id].name)).join(', ') || 'Chưa chọn vai nào.'}</p></details>${r.english==='Custom Random Role'&&!readOnly?'<button class="secondary" data-action="custom-pool">Chọn danh sách rút</button>':''}`:''}`;modal.showModal()}
function libraryCards(){const entries=Object.entries(ROLES).filter(([k])=>roleMatches(k,libraryQuery,roleFilter,true)).sort((a,b)=>a[1].name.localeCompare(b[1].name,'vi'));return `<p class="search-count">${entries.length} kết quả</p><section class="library">${entries.slice(0,libraryLimit).map(([k,r])=>`<article class="role-card"><div class="role-symbol role-symbol-art">${roleArtwork(k)}</div><div class="faction">${r.team}</div><h2>${r.name}</h2><div class="english-name">${r.english}</div><span class="engine-badge ${r.engine}">${roleBadge(k)}</span><p>${esc(roleSummary(r))}</p><button class="text-btn" data-action="role-info" data-role="${k}">Xem chi tiết</button></article>`).join('')||'<p class="empty">Không tìm thấy vai. Hãy thử từ khóa khác.</p><button class="secondary" data-action="library-reset">Xóa tìm kiếm và bộ lọc</button>'}</section>${entries.length>libraryLimit?'<button class="secondary" data-action="library-more">Xem thêm 24 vai</button>':''}`}
let suggestionsOpen=false,setupUndo=null;
function rememberRoleSetup(){setupUndo=structuredClone({roles:state.roles,preset:state.preset,settings:state.settings,houseRules:state.houseRules,customPool:state.customPool})}
function undoRoleSetup(){if(!setupUndo)return false;Object.assign(state,setupUndo);setupUndo=null;save();return true}
function choosePreset(id){rememberRoleSetup();applyPreset(id);suggestionsOpen=false}
function closeSuggestions(){suggestionsOpen=false;document.getElementById('setupSuggestions')?.removeAttribute('open')}
function resetRoleSearch(library=false){if(library){libraryQuery='';roleFilter='all';libraryLimit=24}else{pickerQuery='';pickerFilter='all';pickerLimit=20}}
const SETUP_PROFILES={
 inheritance:{name:'Kế thừa & phân tích',min:10,max:24,level:'Khó · máy xử lý',minutes:5,origin:'Bộ tự động mới · V7',why:'Nhà phân tích đọc hai hào quang, Tiên tri tập sự giữ mạch điều tra khi người soi chết, Sói con tạo sức ép cho bầy.',tip:'Sói con đặt dấu trước lúc chết. Tiên tri tập sự chỉ kế thừa các vai điều tra tự động được hỗ trợ; mọi chuyển vai được kiểm tra riêng từ đêm 2.'},
 intro:{name:'Ván nhập môn',min:5,max:7,level:'Dễ',minutes:3,origin:'Bản rút gọn cho nhóm nhỏ',why:'Chỉ Sói, Tiên tri và Dân làng. Học suy luận trước, chưa cần nhớ nhiều kỹ năng.',tip:'Nhóm 5 đến 6 người chỉ nên có một Sói; một lượt đoán sai có thể quyết định ván.'},
 miller:{name:'Cổ điển · ít kỹ năng',min:8,max:24,level:'Dễ',minutes:4,origin:'Kiểu Miller’s Hollow',why:'Một Tiên tri cung cấp thông tin; phần lớn người chơi tập trung tranh luận và đánh lạc hướng.',tip:'Từ 19 người, số Sói được điều chỉnh cho trang. Có thể chơi một ván này trước khi thêm vai mới.'},
 classic:{name:'Sói · Tiên tri · Bảo vệ',min:7,max:24,level:'Dễ',minutes:4,origin:'Kiểu Werewolf của Stellar Factory',why:'Có điều tra và một vai cứu người, ít lượt thức đêm nên dễ dẫn cho nhóm mới.',tip:'Bảo vệ dùng luật của trang: không bảo vệ cùng người hai đêm liên tiếp. Số Sói nhóm lớn đã được điều chỉnh.'},
 special:{name:'Tiệc bạn bè',min:8,max:24,level:'Vừa',minutes:5,origin:'Bộ phối cho nhóm đã quen',why:'Thêm Phù thủy, Thợ săn rồi Cupid khi đủ người, tạo bất ngờ mà vẫn giữ nhiều Dân làng.',tip:'Từ 12 người có tình nhân; từ 16 người thêm Chán đời. Nhớ giải thích điều kiện thắng riêng.'},
 advanced:{name:'Đấu trí nâng cao',min:10,max:24,level:'Khó',minutes:5,origin:'Bộ phối theo hướng Ultimate Werewolf',why:'Điều tra bằng hào quang và so sánh phe đối đầu Sói pháp sư. Hợp nhóm thích phân tích thông tin.',tip:'Từ 18 người thêm Sát nhân thành phe thứ ba. Các bộ phối chỉ là điểm bắt đầu, cần điều chỉnh theo nhóm.'},
 expanded:{name:'Khám phá vai mở rộng',min:12,max:24,level:'Khó · có quản trò',minutes:5,origin:'Bộ phối vai Wolvesville cho chơi trực tiếp',why:'Sói đầu đàn, Sói tiên tri, Đồng cốt và Đứa trẻ hoa tạo thêm thông tin lẫn khả năng cứu người.',tip:'Quản trò tự xử lý mọi kỹ năng và điều kiện thắng. Nên đọc từng vai trước khi chia.'}
};
function presetAvailable(id,n){const p=SETUP_PROFILES[id];return !!p&&n>=p.min&&n<=p.max}
function recommendedPreset(experience,n){if(n<7)return 'intro';if(n===7)return 'classic';if(experience==='expert'&&n>=10)return 'inheritance';if(experience==='regular')return 'special';return 'miller'}
function presetDeck(id,n){if(!presetAvailable(id,n))id=recommendedPreset('new',n);const r=Object.fromEntries(Object.keys(ROLES).map(k=>[k,0]));const baseW=n<8?1:n<12?2:n<18?3:n<22?4:5;
 if(id==='intro')Object.assign(r,{wolf:1,seer:1});
 if(id==='miller')Object.assign(r,{wolf:baseW,seer:1});
 if(id==='classic')Object.assign(r,{wolf:n<=15?2:2+Math.floor((n-12)/4),seer:1,guard:1});
 if(id==='special'){Object.assign(r,{wolf:Math.floor(n/4),seer:1,guard:1});if(n>=9)r.witch=1;if(n>=10)r.hunter=1;if(n>=12)r.cupid=1;if(n>=16)r.jester=1;}
 if(id==='advanced'){Object.assign(r,{wolf:Math.floor(n/4)-1,shaman:1,aura:1,detective:1,bodyguard:1,witch:1,hunter:1});if(n>=14)r.mayor=1;if(n>=16)r.marksman=1;if(n>=18)r.serial=1;}
 if(id==='inheritance'){Object.assign(r,{wolf:Math.floor(n/4)-1,ext_junior_werewolf:1,seer:1,ext_analyst:1,ext_seer_apprentice:1,guard:1,witch:1});if(n>=14)r.hunter=1;if(n>=16)r.mayor=1;}
 if(id==='expanded'){Object.assign(r,{wolf:Math.floor(n/4)-2,ext_alpha_werewolf:1,ext_wolf_seer:1,aura:1,detective:1,guard:1,witch:1,hunter:1,ext_medium:1,ext_flower_child:1});if(n>=16)r.mayor=1;if(n>=18){r.wolf--;r.ext_junior_werewolf=1}if(n>=20)r.serial=1;}
 r.villager=n-Object.values(r).reduce((a,b)=>a+b,0);return r;
}
function applyPreset(id){const n=state.players.length;if(!presetAvailable(id,n))id=recommendedPreset(state.experience,n);state.roles=presetDeck(id,n);state.preset=id;state.settings.minutes=SETUP_PROFILES[id].minutes;if(id==='expanded')state.settings.mode='moderator';state.setupAdjustment='';pickerFilter='all';pickerQuery='';pickerLimit=20;save()}
function setupSuggestions(){const n=state.players.length,experience=state.experience||'new',recommended=recommendedPreset(experience,n);let ids=experience==='expert'?['inheritance','advanced','expanded']:experience==='regular'?['special','classic','miller']:['intro','miller','classic'];ids=[...new Set([recommended,...ids])].filter(id=>presetAvailable(id,n));return `<details id="setupSuggestions" class="setup-suggestions" ${suggestionsOpen?'open':''}><summary><span><b>Chưa biết chọn vai? Xem bộ gợi ý</b><small>${n} người · gợi ý ${SETUP_PROFILES[recommended].name}</small></span><span class="details-arrow" aria-hidden="true">⌄</span></summary><div class="suggestions-content"><div class="suggestions-head"><div><div class="eyebrow">Chọn nhanh · V7</div><h2 id="suggestionsTitle">Chưa biết xếp vai? Chọn một bộ cho ${n} người.</h2><p>Chỉ tính người nhận vai, không tính quản trò. Bộ tự cập nhật khi đổi số người.</p></div><label class="experience-field"><span>Nhóm của bạn</span><select id="groupExperience"><option value="new" ${experience==='new'?'selected':''}>Mới chơi / có người mới</option><option value="regular" ${experience==='regular'?'selected':''}>Đã chơi vài ván</option><option value="expert" ${experience==='expert'?'selected':''}>Chơi lâu năm, thích đấu trí</option></select></label></div><div class="suggestion-cards">${ids.map(id=>{const p=SETUP_PROFILES[id],r=presetDeck(id,n),active=state.preset===id;return `<article class="suggestion-card ${active?'active':''}"><div class="suggestion-tags"><span>${id===recommended?'Đề xuất cho nhóm':''}</span><small>${p.level} · ${p.minutes} phút/ngày</small></div><h3>${p.name}</h3><p class="suggestion-origin">${p.origin}</p><p>${p.why}</p><div class="preset-composition">${Object.entries(r).filter(([,v])=>v>0).map(([k,v])=>`<span>${ROLES[k].name} <b>×${v}</b></span>`).join('')}</div><p class="suggestion-tip">${p.tip}</p><button class="${active?'secondary':'primary'}" data-action="preset" data-value="${id}" aria-label="Dùng bộ ${p.name}">${active?'Đang dùng bộ này':'Dùng bộ này'} · ${n} vai</button></article>`}).join('')}</div><p class="suggestions-note">Các bộ phối đã điều chỉnh theo luật của trang, không bảo đảm cân bằng với mọi nhóm. Có thể đổi từng vai sau khi áp dụng.</p></div></details>`}
function presetSelector(){return `<div class="preset-selector"><span><label for="presetSelect">Bộ vai hiện tại</label> <button class="text-btn undo-setup" data-action="undo-setup" ${setupUndo?'':'disabled'} type="button">↶ Hoàn tác chỉnh vai</button></span><select id="presetSelect" aria-label="Bộ vai hiện tại"><option value="custom" ${state.preset==='custom'?'selected':''}>Tự chọn từng vai</option>${Object.entries(SETUP_PROFILES).map(([id,p])=>`<option value="${id}" ${state.preset===id?'selected':''} ${presetAvailable(id,state.players.length)?'':'disabled'}>${p.name}${presetAvailable(id,state.players.length)?'':' · '+p.min+' đến '+p.max+' người'}</option>`).join('')}</select></div>`}
function roleSlots(){const n=state.players.length,t=totalRoles(),full=t>=n;return `<div class="role-slots ${full?'full':''}" role="status"><strong>Đã chọn ${t} / ${n} vai</strong><span>${full?'Đã đủ vai. Giảm một vai trước khi thêm vai khác.':'Còn '+(n-t)+' chỗ để chọn vai.'}</span>${!full?'<button class="text-btn" data-action="fill-villagers">Điền Dân làng vào chỗ trống</button>':''}</div>`}
function canAddRole(k){return !!ROLES[k]&&totalRoles()<state.players.length&&(state.roles[k]||0)<roleLimit(k)}
function changeRole(k,delta){if(!ROLES[k]||![-1,1].includes(delta)||delta>0&&!canAddRole(k)||delta<0&&!(state.roles[k]>0))return false;rememberRoleSetup();state.roles[k]=(state.roles[k]||0)+delta;state.preset='custom';state.setupAdjustment='';if(needsModerator())state.settings.mode='moderator';save();return true}
function trimRoleSelection(roles,capacity){const cleaned=Object.fromEntries(Object.keys(ROLES).map(k=>[k,Math.max(0,Math.min(roleLimit(k),Math.floor(Number(roles?.[k])||0)))]));let overflow=Object.values(cleaned).reduce((a,b)=>a+b,0)-capacity;const removed=[];for(const k of ['villager',...Object.keys(ROLES).filter(k=>k!=='villager'&&k!=='wolf').reverse(),'wolf']){if(overflow<=0)break;const amount=Math.min(cleaned[k],overflow);if(amount){cleaned[k]-=amount;overflow-=amount;removed.push(ROLES[k].name+' ×'+amount)}}return {roles:cleaned,removed}}
function resizeSetup(){setupUndo=null;if(state.preset!=='custom')applyPreset(state.preset);else save()}
function removeSetupPlayer(index,dropRole){if(state.players.length<=5||!state.players[index])return false;const n=state.players.length;if(state.preset==='custom'&&totalRoles()>=n){if(!dropRole&&state.roles.villager>0)dropRole='villager';if(!dropRole){modal.innerHTML=`<div class="dialog-head"><h2>Bớt người chơi và một vai</h2><button class="close" data-action="close" aria-label="Đóng">×</button></div><p>Chọn vai cần bỏ để bộ còn đúng ${n-1} người. Các vai khác được giữ lại.</p><div class="remove-role-options">${Object.entries(state.roles).filter(([,v])=>v>0).map(([k,v])=>`<button class="secondary" data-action="remove-with-role" data-index="${index}" data-role="${k}">Bỏ 1 ${ROLES[k].name} (đang có ${v})</button>`).join('')}</div>`;modal.showModal();return false}if(!(state.roles[dropRole]>0))return false;state.roles[dropRole]--;toast('Đã bớt 1 '+ROLES[dropRole].name+' cùng người chơi.')}state.players.splice(index,1);state.photos.splice(index,1);resizeSetup();return true}

const DEFAULT={players:Array.from({length:8},(_,i)=>'Người chơi '+(i+1)),roles:{...Object.fromEntries(Object.keys(ROLES).map(k=>[k,0])),wolf:2,villager:4,seer:1,guard:1,witch:0},preset:'classic',experience:'new',setupAdjustment:'',photos:[],houseRules:{},customPool:[],savedDecks:[],settings:{mode:'auto',minutes:3,revealDeath:false,voice:false},game:null};
function readStore(){try{const v=JSON.parse(localStorage.getItem('demlang-v1'));if(v&&Array.isArray(v.players)&&v.players.length>=5&&v.players.length<=24){const fixed=trimRoleSelection(v.roles||DEFAULT.roles,v.players.length);return {...DEFAULT,...v,roles:fixed.roles,savedDecks:cleanSavedDecks(v.savedDecks),experience:['new','regular','expert'].includes(v.experience)?v.experience:'new',setupAdjustment:fixed.removed.length?'Bộ đã lưu được thu gọn theo số người. Đã bớt: '+fixed.removed.join(', ')+'.':v.setupAdjustment||'',photos:Array.isArray(v.photos)?v.photos.map(cleanPhoto):[],houseRules:v.houseRules||{},customPool:Array.isArray(v.customPool)?v.customPool:[],settings:{...DEFAULT.settings,...v.settings}}}}catch(e){}return structuredClone(DEFAULT)}
let state=readStore(),page='play',secret=false,selected=[],nightResult=null,expanded=false,timerInterval=null,timerEnd=0,timerLeft=0,timerRunning=false;
const app=document.getElementById('app'),modal=document.getElementById('modal');
ensureGame(state.game);
if(needsModerator())state.settings.mode='moderator';
let roleFilter='all';
const esc=s=>String(s).normalize('NFC').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){if(window.roomUI?.isBoard())return window.roomUI.saveBoard();try{localStorage.setItem('demlang-v1',JSON.stringify(state));return true}catch(e){toast('Không lưu được trên thiết bị. Hãy giảm ảnh hoặc giữ trang mở trong ván.');return false}}
function toast(s){const el=document.getElementById('toast');el.textContent=s;el.classList.add('visible');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>el.classList.remove('visible'),3200)}
const alive=()=>state.game.players.filter(p=>p.alive);
const byId=id=>state.game.players.find(p=>p.id===id);
function totalRoles(){return Object.values(state.roles).reduce((a,b)=>a+b,0)}

function setup(){if(window.roomUI?.isBoard())return '<section class="game-stage"><a class="primary" href="?online=1">Về phòng nhiều máy</a><button class="secondary" data-action="resume">Tiếp tục điều hành</button></section>';const n=state.players.length,t=totalRoles(),wolf=wolfCount(),solo=Object.entries(state.roles).reduce((a,[k,n])=>a+(['solo','neutral','random'].includes(ROLES[k].group)?n:0),0),error=configError();return `<div class="page-heading"><h1>Ma Sói Đêm Làng</h1><p>Chơi cùng 5 đến 24 người trên một thiết bị.</p></div>${state.game?`<div class="resume"><div><p>Ván đang lưu</p><small>Ván đã lưu · ${state.game.players.length} người · ${['over','manual-over'].includes(state.game.stage)?'Đã kết thúc':'Ngày '+state.game.round}</small></div><button class="primary" data-action="resume">${['over','manual-over'].includes(state.game.stage)?'Xem kết quả':'Tiếp tục ván'} →</button></div>`:''}<div class="workspace-head"><div><h2>Thiết lập ván chơi</h2></div><div class="steps"><span class="active"><b>1</b> Thiết lập</span><span><b>2</b> Nhận vai</span><span><b>3</b> Vào làng</span></div></div>${setupSuggestions()}${state.setupAdjustment?`<p class="setup-adjustment">${esc(state.setupAdjustment)} <button class="text-btn" data-action="dismiss-adjustment">Đã hiểu</button></p>`:''}<section class="setup-grid"><div class="panel" id="setupPlayers"><div class="panel-head"><div class="panel-title"><span class="symbol">♙</span><h3>Người chơi</h3></div><span class="count-badge">${n} / 24</span></div><div class="panel-body"><div class="players-list">${state.players.map((p,i)=>`<div class="player-input"><button class="player-photo" data-action="photo-open" data-index="${i}" aria-label="Ảnh người chơi ${i+1}">${avatar({id:i,name:p,photo:state.photos[i]})}<span class="camera-badge">＋</span></button><input aria-label="Tên người chơi ${i+1}" data-name="${i}" value="${esc(p)}" maxlength="28"><button data-action="remove" data-index="${i}" aria-label="Xóa người chơi ${i+1}" ${n<=5?'disabled':''}>×</button></div>`).join('')}</div><button class="add-btn" data-action="add" ${n>=24?'disabled':''}>＋ Thêm người chơi</button><p class="hint">Đặt tên để cả làng dễ gọi nhau.<br><span class="gold">Quản trò riêng không tính vào danh sách.</span></p><hr class="panel-rule"><label class="mode-label" for="mode">Ai sẽ dẫn ván chơi?</label><div class="segmented"><button data-action="mode" data-value="auto" ${needsModerator()?'disabled':''} class="${state.settings.mode==='auto'?'selected':''}">◉ Máy dẫn lượt</button><button data-action="mode" data-value="moderator" class="${state.settings.mode==='moderator'?'selected':''}">♙ Có quản trò</button></div><p class="hint">${needsModerator()?'Bộ này có vai cần quản trò. Muốn máy tự dẫn, hãy dùng bộ chỉ gồm vai Máy xử lý.':state.settings.mode==='auto'?'Mọi người đều được chơi. Vai được gọi tự cầm máy để thực hiện kỹ năng.':'Một người ngoài danh sách giữ máy, xem vai và điều khiển ván.'}</p></div></div><div class="panel" id="setupRoles"><div class="panel-head"><div class="panel-title"><span class="symbol">♧</span><h3>Bộ vai</h3></div><button class="text-btn" data-page="roles">Xem sổ vai ↗</button></div><div class="panel-body">${presetSelector()}${deckActions()}${rolePicker()}</div></div><aside class="panel summary"><div><div class="summary-label">NGÔI LÀNG ĐÊM NAY</div><div class="summary-number">${n}<small>người chơi</small></div><div class="balance"><span style="width:${Math.max(1,wolf)/Math.max(1,t)*100}%;background:#9b6d5c"></span><span style="flex:1;background:#80906f"></span>${solo?'<span style="width:10%;background:#b3a273"></span>':''}</div><div class="balance-key"><span>● <b>${wolf}</b> Sói</span><span>● <b>${t-wolf-solo}</b> Làng${solo?' · '+solo+' riêng':''}</span></div><hr class="summary-rule"><div class="setting-line"><span>Thảo luận mỗi ngày</span><b>${state.settings.minutes} phút</b></div><div class="setting-line"><span>Lộ vai khi bị loại</span><b>${state.settings.revealDeath?'Có':'Không'}</b></div><div class="setting-line"><span>Đọc lời dẫn</span><b>${state.settings.voice?'Bật':'Tắt'}</b></div><button class="text-btn" data-action="settings">Tùy chỉnh luật chơi ↗</button></div><div>${error?`<p class="error">${error}</p>`:'<p class="hint" style="text-align:left">✧ Bộ vai đã sẵn sàng.</p>'}${needsModerator()?'<p class="assist-note">Bộ có vai cần quản trò. Quản trò xử lý mọi kỹ năng và kết quả trong ván này.</p>':''}<button class="primary start" data-action="start" ${error?'disabled':''}><span>Chia vai & bắt đầu</span><span>→</span></button><p class="hint">Mỗi người chỉ được biết vai của mình.</p><p class="hint">${t===n?'Đã đủ '+n+' vai. Giảm một vai nếu muốn thay.':'Đã chọn '+t+' / '+n+' vai.'}</p></div></aside></section><div class="intro-note"><span>Chỉ cần một chiếc điện thoại. Không cần bộ bài.</span><span>Vai được xáo ngẫu nhiên cho mỗi ván.</span></div><nav class="mobile-setup-bar" aria-label="Thao tác thiết lập"><a href="#setupPlayers">Người chơi</a><a href="#setupRoles">Bộ vai ${t}/${n}</a><button class="primary" data-action="start" ${error?'disabled':''}>Vào ván →</button></nav>`}
function library(){return `<div class="page-heading"><h1>Sổ vai</h1><p>150 mục: 143 vai và 7 nhóm chia ngẫu nhiên. Vai có nhãn Cần quản trò dùng bảng điều khiển hỗ trợ, không tự xử lý kỹ năng.</p></div><div class="library-search"><label class="search-label" for="librarySearch">Tìm tên hoặc kỹ năng</label><div class="search-field"><span aria-hidden="true">⌕</span><input id="librarySearch" data-library-search value="${esc(libraryQuery)}" placeholder="Nhập tên Việt, tên Anh hoặc kỹ năng…" autocomplete="off"><button data-action="library-clear" aria-label="Xóa tìm kiếm sổ vai">×</button></div></div><div class="role-filters">${[['all','Tất cả'],['village','Phe Làng'],['wolf','Phe Sói'],['solo','Phe riêng'],['neutral','Chưa có phe'],['random','Ngẫu nhiên'],['auto','Máy xử lý'],['guide','Cần quản trò']].map(([k,n])=>`<button class="secondary ${roleFilter===k?'chosen':''}" data-action="filter" data-value="${k}">${n}</button>`).join('')}</div><div id="libraryResults">${libraryCards()}</div>${extraRoleArtwork()}<div class="actions"><button class="secondary" data-page="play">← Về bàn chơi</button></div>`}
function rules(){return `<div class="page-heading"><div class="eyebrow">Bạn bè ngoài đời. Đối thủ trong làng.</div><h1>Luật của màn đêm</h1><p>Chơi trực tiếp cùng 5 đến 24 người trên một thiết bị.</p><p class="assist-note">Bộ có vai Cần quản trò: quản trò tự xử lý mọi kỹ năng, thứ tự gọi và điều kiện thắng theo mô tả vai; máy chỉ hỗ trợ ghi nhận. Luật tự động bên dưới áp dụng cho 21 vai có nhãn Máy xử lý.</p></div><section class="rules-grid"><article><h2>Một ván chơi diễn ra thế nào?</h2><ol><li><strong>Chuẩn bị:</strong> nhập tên người chơi, chọn bộ vai. Quản trò riêng không tham gia nhận vai.</li><li><strong>Nhận vai:</strong> chuyền máy theo tên. Chỉ mở vai khi đã cầm máy một mình; ẩn vai trước khi đưa cho người tiếp theo.</li><li><strong>Đêm:</strong> mọi người nhắm mắt. Chỉ vai được gọi mở mắt và cầm máy. Lần lượt: Cupid (đêm đầu), đôi tình nhân (đêm đầu), Thợ săn, Bảo vệ, Vệ sĩ, Sói pháp sư, bầy Sói, Sát nhân, Tiên tri, Tiên tri hào quang, Thám tử, Phù thủy và Cung thủ. Máy chỉ gọi những vai có trong bộ, kể cả đã bị loại để giữ kín thông tin. Không đọc tên hay kết quả kỹ năng ra tiếng.</li><li><strong>Bình minh:</strong> máy xử lý các hành động và công bố người bị loại. Thợ săn thức mỗi đêm để đặt mục tiêu. Nếu chết, phát súng tự động xử lý theo dấu đã chọn trước khi công bố bình minh.</li><li><strong>Ban ngày:</strong> thảo luận, biện hộ rồi giơ tay bỏ phiếu. Nhập số phiếu vào máy; mỗi người còn sống có một lá phiếu; Thị trưởng đã công khai được tính hai. Dùng menu Kỹ năng ban ngày để dùng nước thánh, súng hoặc tên trước khi chốt phiếu. Hòa phiếu hoặc tất cả bỏ qua thì không treo ai.</li><li><strong>Lặp lại:</strong> đêm và ngày tiếp diễn cho đến khi một phe thắng. Cuối ván mới mở toàn bộ vai.</li></ol></article><article><h2>Điều kiện thắng</h2><p class="reduced"><strong>Phe Làng:</strong> không còn Sói và Sát nhân sống.<br><br><strong>Phe Sói:</strong> số Sói sống bằng hoặc nhiều hơn những người còn lại, đồng thời không còn Sát nhân.<br><br><strong>Sát nhân:</strong> là người cuối cùng còn sống.<br><br><strong>Chán đời:</strong> thắng ngay nếu bị treo cổ ban ngày.<br><br><strong>Đôi tình nhân khác phe:</strong> nếu cả hai còn sống, họ ngăn kết thúc theo phe thông thường và chỉ thắng khi là hai người cuối cùng. Nếu một người chết, người kia chết theo.</p><hr class="panel-rule"><h2>Chơi kín & chơi offline</h2><p class="reduced">Giữ màn hình khỏi tầm nhìn người khác. Khi đổi ứng dụng hoặc tải lại trang, vai bí mật sẽ được che.<br><br>Tải bản HTML qua nút cuối trang và mở file đó bằng trình duyệt để chơi hoàn toàn không cần mạng.<br><br>Giọng đọc phụ thuộc tiếng Việt trên thiết bị và có thể cần mạng. Lời dẫn dạng chữ luôn dùng được offline.</p></article></section>`}
let pickerScrollTop = 0;

function preservePickerScroll(update) {
  const findList = () => document.getElementById('pickerResults')?.querySelector?.('.catalog-scroll');
  const previousList = findList();
  if (previousList) pickerScrollTop = previousList.scrollTop;
  update();
  const nextList = findList();
  if (nextList) nextList.scrollTop = pickerScrollTop;
}

function render() {
  if(page==='online' && window.roomUI) return window.roomUI.render();

  document.querySelectorAll('.nav').forEach(el => {
    el.classList.toggle('active', el.dataset.page === page || page === 'game' && el.dataset.page === 'play');
  });
  preservePickerScroll(() => {
    app.innerHTML = page === 'play' ? setup() : page === 'roles' ? library() : page === 'rules' ? rules() : gameView();
    document.querySelectorAll('[data-icon]').forEach(el => el.innerHTML = icon(el.dataset.icon));
  });
}

function refreshPickerResults() {
  preservePickerScroll(() => {
    document.getElementById('pickerResults').innerHTML = pickerRows();
  });
}
function settings(){modal.innerHTML=`<div class="dialog-head"><h2>Luật chơi</h2><button class="close" data-action="close" aria-label="Đóng">×</button></div><form id="settingsForm"><label class="field"><span>Người dẫn ván</span><select name="mode"><option value="auto" ${needsModerator()?'disabled':''} ${state.settings.mode==='auto'?'selected':''}>Máy làm quản trò</option><option value="moderator" ${state.settings.mode==='moderator'?'selected':''}>Có quản trò riêng</option></select><small>Áp dụng cho ván mới. Máy dẫn bằng chữ; có thể bật giọng đọc bên dưới.</small></label><label class="field"><span>Thảo luận mỗi ngày</span><select name="minutes">${[1,2,3,4,5,7,10].map(n=>`<option value="${n}" ${state.settings.minutes===n?'selected':''}>${n} phút</option>`).join('')}</select></label><label class="check"><input type="checkbox" name="revealDeath" ${state.settings.revealDeath?'checked':''}><span>Lộ vai khi bị loại<small>Mặc định tắt để giữ bí mật cho đến hết ván.</small></span></label><label class="check"><input type="checkbox" name="voice" ${state.settings.voice?'checked':''}><span>Đọc lời dẫn ban đêm<small>Chỉ dùng ở chế độ Máy làm quản trò. Cần giọng tiếng Việt trên thiết bị.</small></span></label><button type="button" class="secondary" data-action="voice-preview">Nghe thử lời dẫn</button><p class="hint">Bảo vệ không chọn cùng người hai đêm liên tiếp. Phù thủy được tự cứu. Hòa phiếu không treo ai. Sói thắng khi cân bằng quân số, trừ khi Sát nhân hoặc đôi tình nhân khác phe còn sống. Thợ săn được gọi mỗi đêm để đặt mục tiêu.</p><div class="actions"><button class="primary" type="submit">Lưu thiết lập</button></div></form>`;modal.showModal()}
function confirmBox(title,body,action,label='Xác nhận'){modal.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="close" data-action="close" aria-label="Đóng">×</button></div><p class="reduced">${body}</p><div class="actions"><button class="secondary" data-action="close">Quay lại</button><button class="primary" data-action="${action}">${label}</button></div>`;modal.showModal()}
function shuffle(a){for(let i=a.length-1;i>0;i--){const limit=4294967296-(4294967296%(i+1));let x;do{x=crypto.getRandomValues(new Uint32Array(1))[0]}while(x>=limit);const j=x%(i+1);[a[i],a[j]]=[a[j],a[i]]}return a}
function makeGame(players,manual,stage='deal'){
  const game={players,manual,houseRules:{...state.houseRules},settings:{...state.settings},stage,dealIndex:0,round:1,queue:[],nightIndex:0,night:{},lovers:[],lastGuard:null,healUsed:false,poisonUsed:false,hunterUsed:false,hunters:[],afterHunter:'dawn',log:[],dawn:[],votes:{},winner:null};
  ensureGame(game);
  ensureModerator(game);
  game.voteMode='ballots';
  return game;
}
function newGame(){if(window.roomUI?.isBoard())return toast('Hãy tạo phòng mới để chơi lại.');const names=state.players.map(x=>x.trim().normalize('NFC'));if(names.some(x=>!x))return toast('Điền tên cho tất cả người chơi.');if(new Set(names.map(x=>x.toLocaleLowerCase('vi'))).size!==names.length)return toast('Mỗi người cần một tên khác nhau.');const error=configError();if(error)return toast(error);const deck=buildDeck();if(!deck)return toast('Nhóm rút không đủ vai hợp lệ. Hãy mở rộng danh sách ngẫu nhiên hoặc giảm số ô.');const manual=needsModerator()||state.settings.mode==='moderator';state.game=makeGame(names.map((name,i)=>({id:i,name,photo:cleanPhoto(state.photos[i]),role:deck[i],initialRole:deck[i],alive:true})),manual);page='game';secret=false;selected=[];save();render();window.scrollTo(0,0)}
function addLog(s){state.game.log.push(s)}
function beginNight(){stopTimer();const g=state.game;ensureGame(g);g.stage='night';g.night={};g.nightIndex=0;g.statusIndex=0;g.queue=[];if(g.round===1&&alive().some(p=>p.role==='cupid'))g.queue.push('cupid','lovers');if(g.round>1&&g.players.some(p=>['cursed','ext_seer_apprentice','ext_junior_werewolf'].includes(p.initialRole)))g.queue.push('status');for(const r of NIGHT_ORDER)if(r==='wolf'?g.players.some(isWolf):g.players.some(p=>p.role===r||p.initialRole===r))g.queue.push(r);secret=false;selected=[];nightResult=null;g.votes={};g.ballots={};g.publicReport=[];addLog('Đêm '+g.round+' bắt đầu.');save();render()}
function speak(s,preview=false){if(!preview&&!state.game?.settings.voice)return;if(!('speechSynthesis'in window)){toast('Trình duyệt không hỗ trợ đọc lời dẫn.');return;}const voices=speechSynthesis.getVoices(),v=voices.find(x=>x.lang.startsWith('vi'));if(!v){toast('Thiết bị chưa có giọng tiếng Việt. Hãy đọc lời dẫn trên màn hình.');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(s);u.lang='vi-VN';u.voice=v;u.rate=.85;speechSynthesis.speak(u)}
function nextNight(){const g=state.game;g.nightIndex++;window.scrollTo(0,0);secret=false;selected=[];nightResult=null;if('speechSynthesis'in window)speechSynthesis.cancel();if(g.nightIndex>=g.queue.length)resolveNight();else{save();render()}}
function eliminate(ids,cause){const g=state.game,newDead=[],pending=[...new Set(ids)].filter(x=>x!==null&&x!==undefined);while(pending.length){const id=pending.shift(),p=byId(id);if(!p||!p.alive)continue;p.alive=false;newDead.push(id);addLog(p.name+' bị loại ('+cause+').');if(g.lovers.includes(id)){const mate=g.lovers.find(x=>x!==id);if(byId(mate)?.alive)pending.push(mate)}if(p.role==='hunter'&&!g.hunterUsed){g.hunterUsed=true;if(g.hunterTarget!=null&&byId(g.hunterTarget)?.alive){pending.push(g.hunterTarget);addLog('Phát súng Thợ săn kéo theo '+byId(g.hunterTarget).name+'.')}}if(p.role==='ext_junior_werewolf'&&!g.juniorUsed){g.juniorUsed=true;const target=byId(g.juniorTarget);if(target?.alive&&!isWolf(target)){if(target.role==='cursed'){target.role='wolf';addLog(target.name+' hóa Ma sói do dấu Sói con.')}else pending.push(target.id)}}}if(!g.manual){const informer=newDead.map(byId).find(p=>['seer','aura','detective','ext_analyst'].includes(p.role));if(informer)for(const p of alive().filter(p=>p.role==='ext_seer_apprentice')){p.role=informer.role;p.infos=structuredClone(informer.infos||[]);p.restRound=0;addLog(p.name+' kế thừa '+ROLES[informer.role].name+'.')}}return newDead}
function resolveNight(){const g=state.game,n=g.night;ensureGame(g);g.lastGuard=n.guard??null;const deaths=[];function attack(id,kind){const p=byId(id);if(!p?.alive)return;if(kind==='wolf'&&(n.heal||p.role==='serial'))return;if(id===n.guard)return;const bg=alive().find(p=>p.role==='bodyguard');const recipient=bg&&n.bodyguard===id?bg:p;if(recipient.role==='bodyguard'){g.bodyguardHits++;if(g.bodyguardHits<2){addLog('Vệ sĩ chịu một đòn tấn công.');return}}if(kind==='wolf'&&recipient.role==='cursed'){recipient.role='wolf';addLog(recipient.name+' chuyển từ Người bị nguyền thành Ma sói.');return}deaths.push(recipient.id)}if(n.serial!=null)attack(n.serial,'serial');if(n.wolf!=null)attack(n.wolf,'wolf');if(n.poison!=null)deaths.push(n.poison);if(n.marksmanShot!=null){const p=byId(n.marksmanShot),shooter=alive().find(p=>p.role==='marksman');if(p&&shooter)deaths.push(faction(p)==='village'?shooter.id:p.id)}g.dawn=eliminate(deaths,'đêm '+g.round);g.afterHunter='dawn';g.stage='dawn';secret=false;save();render()}
function winner(){const g=state.game,ps=alive(),wolves=ps.filter(isWolf).length,killers=ps.filter(p=>p.role==='serial').length,pair=g.lovers.map(byId);if(!ps.length)return 'draw';const mixed=pair.length===2&&pair.every(p=>p?.alive)&&faction(pair[0])!==faction(pair[1]);if(mixed)return ps.length===2?'lovers':null;if(killers)return ps.length===1?'serial':null;if(!wolves)return 'village';if(wolves>=ps.length-wolves)return 'wolves';return null}
function checkWin(){const w=winner();if(!w)return false;state.game.winner=w;state.game.stage='over';stopTimer();save();return true}
function afterHunter(){const g=state.game;secret=false;selected=[];if(g.hunters.length)g.stage='hunter';else if(g.afterHunter==='dawn')g.stage='dawn';else if(!checkWin()){g.round++;beginNight();return}save();render()}
function targetGrid(players,multiple=false){return `<div class="player-grid">${players.map(p=>`<button class="target ${selected.includes(p.id)?'chosen':''}" data-action="target" data-id="${p.id}" ${multiple?'data-multiple="true"':''}>${avatar(p)}<span>${esc(p.name)}</span></button>`).join('')}</div>`}
function gate(title,text,button='Tôi đã cầm máy'){return `<span class="large-symbol">${icon('moon')}</span><div class="eyebrow">Mọi người khác hãy nhắm mắt</div><h1>${title}</h1><p>${text}</p><button class="primary" data-action="unlock">${button} →</button>`}
function gameView(){const g=state.game;if(!g){page='play';return setup()}if(g.manual&&!['deal','ready'].includes(g.stage))return moderatorView();const head=`<div class="game-wrap"><div class="game-top"><p>${g.stage==='deal'?'CHIA VAI BÍ MẬT':g.stage==='over'?'KẾT THÚC VÁN':'ĐÊM LÀNG · VÒNG '+g.round}</p><div style="display:flex;gap:16px"><button class="text-btn" data-action="veil">◈ Che màn hình</button><button class="text-btn" data-action="exit">Về bàn chơi</button></div></div><section class="game-stage">`;let body='';
 if(g.stage==='deal'){const p=g.players[g.dealIndex],r=ROLES[p.role];body=secret?`<div class="eyebrow">Chỉ ${esc(p.name)} được xem</div><div class="role-reveal">${roleArtwork(p.role, true)}<div class="faction">${r.team}</div><h2>${r.name}</h2><p class="dealt-role-rules">${esc(r.desc)}</p><button class="secondary" data-action="deal-role-info">Xem chi tiết vai</button></div><button class="primary" data-action="deal-next">Ẩn vai & ${g.dealIndex===g.players.length-1?'vào làng':'chuyền máy'} →</button>`:`<span class="large-symbol">${icon('lock')}</span><div class="eyebrow">Người chơi ${g.dealIndex+1} / ${g.players.length}</div>${avatar(p,true)}<h1>${esc(p.name)}</h1><p>Hãy nhận máy, đảm bảo không ai nhìn màn hình.</p><div class="deal-privacy"><label class="check"><input type="checkbox" id="dealPrivacy"><span>Tôi đã nhận máy và chỉ mình tôi nhìn màn hình.</span></label><button class="primary" id="dealOpen" data-action="deal-open" disabled>Xem vai của tôi</button></div><div class="progress"><div style="width:${g.dealIndex/g.players.length*100}%"></div></div>`}
 else if(g.stage==='ready'){body=`<span class="large-symbol">${icon('moon')}</span><div class="eyebrow">${window.roomUI?.isBoard()?'Phòng đã chia vai':'Tất cả đã nhận vai'}</div><h1>Ngôi làng chìm vào giấc ngủ.</h1><p>${window.roomUI?.isBoard()?'Khi mọi người đã đọc thẻ trên điện thoại, quản trò có thể bắt đầu đêm đầu tiên.':g.settings.mode==='moderator'?'Đưa máy cho quản trò. Quản trò không nằm trong danh sách người chơi và sẽ điều khiển các lượt.':'Đặt máy ở giữa. Mọi người nhắm mắt. Khi được gọi, vai đó mở mắt và cầm máy thực hiện kỹ năng. Nhớ ẩn màn hình trước khi đặt xuống.'}</p><p class="hint">${g.manual?'Quản trò giữ máy trong cả ván, ghi kỹ năng và tự xử lý kết quả trên bảng riêng.':'Máy dẫn lượt bằng chữ'+(g.settings.voice?' và giọng đọc trên thiết bị':'')+'. Sau mỗi lượt, bấm gọi vai tiếp theo; người bấm chỉ nhìn màn hình lời gọi chung.'}</p><button class="primary" data-action="begin-night">Bắt đầu đêm đầu tiên →</button>`}
 else if(g.stage==='night')body=nightView();
 else if(g.stage==='power')body=dayPowerView();
 else if(g.stage==='dawn'){body=`<span class="large-symbol">${icon('sun')}</span><div class="eyebrow">Bình minh · Ngày ${g.round}</div><h1>${g.dawn.length?'Đêm qua, làng mất đi…':'Một đêm bình yên.'}</h1><p>${g.dawn.length?g.dawn.map(id=>{const p=byId(id);return '<strong>'+esc(p.name)+'</strong>'+(g.settings.revealDeath?' · '+ROLES[p.role].name:'')}).join('<br>'):'Không có ai bị loại đêm qua. Nhưng Sói vẫn đang ở đây.'}</p><button class="primary" data-action="day">Cả làng thức dậy →</button>`}
 else if(g.stage==='day'){body=`<div class="eyebrow">Ngày ${g.round} · ${alive().length} người còn sống</div><h1>Đã đến lúc nghi ngờ.</h1><p>Ai đang nói thật? Ai giấu đôi nanh sau nụ cười?<br>Thảo luận cùng nhau trước khi đưa ra lá phiếu.</p><div class="timer" id="timer">${formatTime(timerRunning?Math.max(0,Math.ceil((timerEnd-Date.now())/1000)):timerLeft)}</div><div class="actions"><button class="secondary" data-action="timer">${timerRunning?'Tạm dừng':'Bắt đầu đếm giờ'}</button><button class="text-btn" data-action="timer-reset">↻ Đặt lại</button></div><div class="alive-strip">${alive().map(p=>`<span>${esc(p.name)}</span>`).join('')}</div><div class="actions"><button class="secondary" data-action="powers">Kỹ năng ban ngày</button><button class="primary" data-action="vote">Đến lượt bỏ phiếu →</button></div>${publicReportView()}`}
 else if(g.stage==='vote')body=voteView();
 else if(g.stage==='hunter'){const p=byId(g.hunters[0]);body=!secret?gate('Thợ săn, phát súng cuối cùng.',`${esc(p.name)} đã bị loại. Người này cầm máy và chọn một người để bắn, hoặc bỏ qua.`):`<div class="eyebrow">Thợ săn · ${esc(p.name)}</div><h1>Bạn chọn ai đi cùng?</h1><p>Phát súng bỏ qua mọi lớp bảo vệ.</p>${targetGrid(alive())}<div class="actions"><button class="secondary" data-action="hunter-skip">Không bắn</button><button class="primary" data-action="hunter-fire" ${selected.length!==1?'disabled':''}>Bắn & ẩn màn hình</button></div>`}
 else if(g.stage==='over'){const labels={village:['villager','Phe Làng thắng.',''],wolves:['wolf','Phe Sói thắng.',''],lovers:['cupid','Tình yêu chiến thắng.','Hai người cuối cùng, vượt qua mọi phe phái.'],jester:['jester','Chán đời chiến thắng.','Cả làng đã treo đúng người muốn bị treo.'],serial:['serial','Sát nhân chiến thắng.','Một người duy nhất còn sống sau tất cả.'],draw:['moon','Không ai sống sót.','Ván chơi kết thúc hòa.']},v=labels[g.winner];body=`<span class="large-symbol">${icon(v[0])}</span><h1>${v[1]}</h1><p>${v[2]}</p><div class="results-list">${g.players.map(p=>`<div><span class="role-symbol">${icon(p.role)}</span>${avatar(p)}<span><b>${esc(p.name)}</b><small>${ROLES[p.role].name}${p.initialRole&&p.initialRole!==p.role?' (ban đầu: '+ROLES[p.initialRole].name+')':''} · ${p.alive?'Còn sống':'Đã bị loại'}${g.lovers.includes(p.id)?' · ♥':''}</small></span></div>`).join('')}</div><details class="log"><summary>Nhật ký ván chơi</summary><ol>${g.log.map(s=>`<li>${esc(s)}</li>`).join('')}</ol></details><div class="actions"><button class="secondary" data-action="exit">Về bàn chơi</button><button class="primary" data-action="replay">Chơi lại cùng nhóm →</button></div>`}
 if(g.settings.mode==='moderator'&&!['deal','ready','over'].includes(g.stage))body+='<div class="actions"><button class="text-btn" data-action="moderator">♙ Sổ bí mật của quản trò</button></div>';
 return head+body+'</section><p class="hint" style="text-align:center">'+(g.stage==='over'?'Cảm ơn vì đã sống sót. Hoặc đã nói dối rất giỏi.':'Ván được lưu trên thiết bị này. Che màn hình trước khi chuyền máy.')+'</p></div>'}
function apparentFaction(p){return state.game.night.shaman===p.id?'wolf':faction(p)}
function auraOf(p){if(apparentFaction(p)==='wolf')return 'Ác';if(['jester','serial','hunter','witch','gunner','marksman'].includes(p.role))return 'Không rõ';return 'Thiện'}
function investigation(role,ids){const ps=ids.map(byId);if(role==='ext_analyst')return {title:ps.map(p=>p.name+': '+auraOf(p)).join(' · '),names:ps.map(p=>p.name).join(' & ')};if(role==='seer')return {title:apparentFaction(ps[0])==='wolf'?'Là Ma sói.':'Không phải Ma sói.',names:ps.map(p=>p.name).join(' & ')};if(role==='aura')return {title:'Hào quang: '+auraOf(ps[0]),names:ps[0].name};return {title:apparentFaction(ps[0])===apparentFaction(ps[1])?'Cùng phe.':'Khác phe.',names:ps.map(p=>p.name).join(' & ')}}
function nightView(){const g=state.game,r=g.queue[g.nightIndex],role=ROLES[r],performer=r==='wolf'?alive().find(isWolf):alive().find(p=>p.role===r);ensureGame(g);
 if(r==='status'){const ps=alive(),p=ps[g.statusIndex||0];if(!p)return `<h1>Đã kiểm tra xong.</h1><button class="primary" data-action="night-next">Chuyển lượt →</button>`;return !secret?gate('Xin mời '+esc(p.name)+'.','Cả làng tiếp tục nhắm mắt. Từng người còn sống kiểm tra trạng thái trên máy, rồi ẩn trước khi chuyền.','Tôi là '+esc(p.name)):`<div class="eyebrow">Chỉ ${esc(p.name)} được xem</div><h1>Vai hiện tại của bạn</h1><div class="role-reveal"><span class="large-symbol">${icon(p.role)}</span><h2>${ROLES[p.role].name}</h2><div class="faction">${ROLES[p.role].team}</div><p>${p.initialRole!==p.role?'Bạn đã đổi vai. Từ bây giờ làm theo kỹ năng của vai hiện tại.':'Vai và phe của bạn không thay đổi.'}</p>${p.infos?.length?`<details><summary>Sổ kết quả kế thừa</summary>${p.infos.map(x=>`<p>${esc(x)}</p>`).join('')}</details>`:''}</div><button class="primary" data-action="status-next">Ẩn & chuyền máy →</button>`}
 if(!secret)return gate(roleName(r)+', hãy thức dậy.',r==='lovers'?'Chỉ đôi tình nhân mở mắt. Cupid báo hiệu cho hai người bằng cách chạm nhẹ khi mọi người khác nhắm mắt.':'Chỉ vai được gọi mở mắt và cầm máy. Hoàn tất lựa chọn rồi ẩn màn hình trước khi đặt máy xuống. Vai đã bị loại vẫn được gọi để giữ bí mật.','Mở lượt bí mật');
 if(r==='lovers')return `<span class="large-symbol">${icon('cupid')}</span><div class="eyebrow">Bí mật của hai người</div><h1>${g.lovers.map(id=>esc(byId(id).name)).join(' & ')}</h1><p>Một người bị loại thì người kia cũng bị loại. ${g.lovers.length===2&&faction(byId(g.lovers[0]))!==faction(byId(g.lovers[1]))?'Hai bạn khác phe: chỉ thắng khi là hai người cuối cùng.':'Hai bạn cùng phe: thắng cùng phe của mình.'}</p><button class="primary" data-action="night-next">Ẩn & ngủ lại →</button>`;
 if(!performer)return `<span class="large-symbol">${icon('moon')}</span><h1>Không có hành động.</h1><p>Giữ nhịp lượt rồi chuyển tiếp.</p><button class="primary" data-action="night-next">Ẩn & chuyển lượt →</button>`;
 if(['seer','aura','detective','ext_analyst'].includes(r)&&performer.readRound===g.round&&performer.readResult)nightResult=performer.readResult;
 if(['seer','aura','detective','ext_analyst'].includes(r)&&nightResult!==null)return `<span class="large-symbol">${icon(r)}</span><div class="eyebrow">Chỉ ${role.name} được xem</div><h1>${esc(nightResult.names)}</h1><div class="role-reveal"><h2>${esc(nightResult.title)}</h2></div><p>Ghi nhớ kết quả và giữ bí mật.</p><button class="primary" data-action="seer-done">Ẩn kết quả & ngủ lại →</button>`;
 if(r==='ext_seer_apprentice'||r==='ext_analyst'&&performer.restRound===g.round)return `<h1>${r==='ext_analyst'?'Đêm nghỉ kỹ năng.':'Bạn đang chờ kế thừa.'}</h1><p>${ROLES[r].desc}</p><button class="primary" data-action="night-next">Ẩn & ngủ lại →</button>`;
 if(r==='witch'){const victim=g.night.wolf!=null?byId(g.night.wolf):null;return `<div class="eyebrow">Lượt bí mật · Phù thủy</div><h1>Chọn bình thuốc</h1><p>${victim?'Sói chọn tấn công <strong>'+esc(victim.name)+'</strong>.':'Sói không tấn công ai.'} Bình cứu chỉ chặn đòn Sói.</p><label class="check" style="justify-content:center"><input id="healChoice" type="checkbox" ${g.healUsed||!victim?'disabled':''} ${g.night.heal?'checked':''}><span>${g.healUsed?'Bình cứu đã dùng':victim?'Dùng bình cứu để cứu '+esc(victim.name):'Không có mục tiêu để cứu'}</span></label><hr class="panel-rule"><p>${g.poisonUsed?'Bình độc đã dùng.':'Chọn một người để đầu độc, hoặc không chọn để giữ bình.'}</p>${g.poisonUsed?'':targetGrid(alive().filter(p=>p.id!==performer.id))}<button class="primary" data-action="witch-done">Xác nhận & ẩn màn hình →</button>`}
 if(r==='marksman'&&g.arrows===0)return `<h1>Bạn đã hết tên.</h1><p>Tiếp tục suy luận và bỏ phiếu cùng làng.</p><button class="primary" data-action="night-next">Ẩn & ngủ lại →</button>`;
 const pairmate=g.lovers.includes(performer.id)?g.lovers.find(id=>id!==performer.id):null;
 const candidates=r==='ext_junior_werewolf'?alive().filter(p=>!isWolf(p)):r==='ext_analyst'?alive().filter(p=>p.id!==performer.id):r==='wolf'?alive().filter(p=>!isWolf(p)):r==='guard'?alive().filter(p=>p.id!==g.lastGuard):['seer','aura','serial','hunter','marksman'].includes(r)?alive().filter(p=>p.id!==performer.id&&(r!=='marksman'||p.id!==pairmate)):alive();
 const info={ext_junior_werewolf:['Đặt dấu của Sói con.','Chọn người ngoài bầy. Nếu chết, dấu đã chọn sẽ kích hoạt. Người bị nguyền hóa Sói thay vì chết.'],ext_analyst:['Đọc hai hào quang.','Chọn hai người khác nhau, không chọn mình. Hai hào quang giống nhau thì phải nghỉ đêm kế tiếp.'],hunter:['Đặt mục tiêu cho phát súng cuối.','Chọn một người trước khi ngủ lại. Nếu bạn chết, mục tiêu đã chọn sẽ chết theo. Có thể đổi mục tiêu mỗi đêm; chọn Không đặt mục tiêu để bỏ phát súng.'],cupid:['Ghép đôi tình nhân.','Chọn đúng hai người khác nhau, có thể chọn mình. Báo hiệu cho hai người khi cả làng đang nhắm mắt.'],guard:['Bạn sẽ bảo vệ ai?','Có thể chọn mình, nhưng không lặp lại người của đêm trước. Chặn đòn Sói và Sát nhân.'],bodyguard:['Bạn sẽ đỡ đòn cho ai?','Chặn đòn bằng cách nhận thay. Bạn đã nhận '+g.bodyguardHits+'/2 đòn trong cả ván.'],shaman:['Phù phép một người.','Chỉ làm sai kết quả soi trong đêm này, không đổi phe thật.'],wolf:['Bầy Sói chọn nạn nhân.','Tất cả vai phe Sói cùng thống nhất một người. Chỉ một Sói thao tác.'],serial:['Đêm nay, bạn chọn ai?','Tấn công một người. Chỉ bạn sống cuối cùng mới thắng.'],seer:['Bạn muốn soi ai?','Xem một người khác có phải Sói hay không.'],aura:['Bạn muốn đọc hào quang ai?','Hào quang có thể là Thiện, Ác hoặc Không rõ.'],detective:['Hai người có cùng phe?','Chọn đúng hai người khác nhau, có thể chọn mình.'],marksman:['Đánh dấu trước khi giương cung.','Còn '+g.arrows+' mũi tên. Dấu mới chỉ bắn được từ đêm tiếp theo.']},v=info[r],mark=byId(g.mark),ready=mark?.alive&&g.round>g.markRound;
 return `<div class="eyebrow">Lượt bí mật · ${role.name}</div><span class="large-symbol" style="width:48px;height:54px">${icon(r)}</span><h1>${v[0]}</h1><p>${v[1]}</p>${r==='hunter'&&g.hunterTarget!=null?`<p class="hint">Mục tiêu cũ: ${esc(byId(g.hunterTarget).name)}. Lựa chọn mới sẽ thay thế dấu cũ.</p>`:''}${r==='marksman'&&mark?`<p class="hint">Dấu hiện tại: ${esc(mark.name)} · ${ready?'đã sẵn sàng':'chưa thể bắn hoặc mục tiêu đã chết'}.</p>`:''}${targetGrid(candidates,['cupid','detective','ext_analyst'].includes(r))}<div class="actions">${r!=='cupid'?`<button class="secondary" data-action="night-skip">${r==='ext_junior_werewolf'?'Xóa dấu & ngủ lại':r==='hunter'?'Không đặt mục tiêu':r==='marksman'?'Giữ dấu & ngủ lại':'Bỏ qua kỹ năng'}</button>`:''}${r==='marksman'&&ready?'<button class="secondary" data-action="marksman-night-shoot">Bắn dấu hiện tại</button>':''}<button class="primary" data-action="night-confirm" ${selected.length!==(['cupid','detective','ext_analyst'].includes(r)?2:1)?'disabled':''}>${['seer','aura','detective','ext_analyst'].includes(r)?'Xem kết quả':r==='marksman'?'Đặt dấu & ẩn':'Xác nhận & ẩn màn hình'} →</button></div>`
}
function handleNightConfirm(){const g=state.game,r=g.queue[g.nightIndex],need=['cupid','detective','ext_analyst'].includes(r)?2:1;if(selected.length!==need)return;if(['seer','aura','detective','ext_analyst'].includes(r)){if(new Set(selected).size!==need)return;const p=alive().find(p=>p.role===r);if(p?.readRound===g.round&&p.readResult){nightResult=p.readResult;render();return}nightResult=investigation(r,selected);if(p){p.readRound=g.round;p.readResult=structuredClone(nightResult);p.infos??=[];p.infos.push('Đêm '+g.round+': '+nightResult.names+' · '+nightResult.title);if(r==='ext_analyst'&&auraOf(byId(selected[0]))===auraOf(byId(selected[1])))p.restRound=g.round+1}save();render();return}if(r==='ext_junior_werewolf'){if(!byId(selected[0])?.alive||isWolf(byId(selected[0])))return;g.juniorTarget=selected[0];addLog('Sói con đặt dấu '+byId(selected[0]).name+'.')}else if(r==='cupid'){g.lovers=[...selected];addLog('Cupid ghép '+selected.map(id=>byId(id).name).join(' và ')+'.')}else if(r==='hunter'){g.hunterTarget=selected[0];addLog('Đêm '+g.round+': Thợ săn đặt mục tiêu '+byId(selected[0]).name+'.')}else if(r==='marksman'){g.mark=selected[0];g.markRound=g.round;addLog('Đêm '+g.round+': Cung thủ đánh dấu '+byId(selected[0]).name+'.')}else{g.night[r]=selected[0];addLog('Đêm '+g.round+': '+roleName(r)+' chọn '+byId(selected[0]).name+'.')}nextNight();speakNext()}
function speakNext(){const g=state.game;if(g.stage==='night')speak(g.queue[g.nightIndex]==='status'?'Cả làng lần lượt kiểm tra trạng thái trên máy.':roleName(g.queue[g.nightIndex])+', hãy thức dậy.')}
function publicReportView(){const g=state.game;return g.publicReport.length?`<div class="public-report" role="status"><h2>Thông báo của làng</h2>${g.publicReport.map(s=>`<p>${esc(s)}</p>`).join('')}</div>`:''}
function openPowers(){const g=state.game;stopTimer();const powers=['priest','gunner','marksman','mayor'].filter(r=>g.players.some(p=>p.initialRole===r));modal.innerHTML=`<div class="dialog-head"><h2>Kỹ năng ban ngày</h2><button class="close" data-action="close" aria-label="Đóng">×</button></div><p class="hint">Chỉ người có vai tương ứng được sử dụng. Đây là hành động công khai; vai sẽ được công bố khi xác nhận dùng.</p><div class="actions">${powers.length?powers.map(r=>`<button class="secondary" data-action="power-open" data-role="${r}">${ROLES[r].name}</button>`).join(''):'<p>Ván này không có vai dùng kỹ năng ban ngày.</p>'}</div>`;modal.showModal()}
function dayPowerView(){const g=state.game,r=g.powerRole,p=alive().find(p=>p.role===r);if(!secret)return `<span class="large-symbol">${icon(r)}</span><h1>${ROLES[r].name} muốn dùng kỹ năng?</h1><p>Chỉ người giữ vai này được tiếp tục. Khi xác nhận dùng, vai và hành động sẽ công khai với cả làng.</p><div class="actions"><button class="secondary" data-action="power-back">Quay lại thảo luận</button><button class="primary" data-action="unlock">Tôi giữ vai này</button></div>`;const unavailable=!p?'Vai này không còn sống.':r==='priest'&&g.priestUsed?'Nước thánh đã dùng.':r==='gunner'&&(g.bullets<=0||g.gunDay===g.round||g.round<2)?g.round<2?'Xạ thủ chỉ bắn từ ngày 2.':'Đã hết đạn hoặc đã bắn hôm nay.':r==='mayor'&&g.mayorRevealed?'Thị trưởng đã công khai.':r==='marksman'&&(g.arrows<=0||!byId(g.mark)?.alive||g.round<=g.markRound)?'Chưa có dấu hợp lệ đã qua một ngày, hoặc đã hết tên.':null;if(unavailable)return `<h1>Chưa thể dùng kỹ năng.</h1><p>${unavailable}</p><button class="secondary" data-action="power-back">Quay lại thảo luận</button>`;
 if(r==='mayor')return `<h1>Công khai vai Thị trưởng?</h1><p>${esc(p.name)} sẽ lộ vai. Từ bây giờ, lá phiếu của bạn được máy tính trọng số 2.</p><div class="actions"><button class="secondary" data-action="power-back">Giữ bí mật</button><button class="primary" data-action="power-confirm">Công khai vai</button></div>`;
 if(r==='marksman')return `<h1>Bắn dấu của Cung thủ?</h1><p>Mục tiêu: <strong>${esc(byId(g.mark).name)}</strong>. Nếu người đó thuộc Làng, bạn chết thay. Còn ${g.arrows} mũi tên.</p><div class="actions"><button class="secondary" data-action="power-back">Chưa bắn</button><button class="primary" data-action="power-confirm">Xác nhận dùng tên</button></div>`;
 const mate=g.lovers.includes(p.id)?g.lovers.find(id=>id!==p.id):null;return `<div class="eyebrow">${ROLES[r].name} · ${esc(p.name)}</div><h1>${r==='priest'?'Bạn sẽ dùng nước thánh với ai?':'Chọn người để bắn.'}</h1><p>${r==='priest'?'Nếu chọn người không phải Sói, chính bạn sẽ bị loại.':'Còn '+g.bullets+' viên đạn. Bắn nhầm Làng vẫn giết mục tiêu.'}</p>${targetGrid(alive().filter(t=>t.id!==p.id&&(r!=='gunner'||t.id!==mate)))}<div class="actions"><button class="secondary" data-action="power-back">Chưa dùng</button><button class="primary" data-action="power-confirm" ${selected.length!==1?'disabled':''}>Xác nhận dùng kỹ năng</button></div>`
}
function useDayPower(){const g=state.game,r=g.powerRole,p=alive().find(p=>p.role===r);if(!p)return;let deaths=[],report='';if(r==='mayor'){if(g.mayorRevealed)return;g.mayorRevealed=true;report=p.name+' công khai vai Thị trưởng. Lá phiếu từ nay tính 2.'}else if(r==='marksman'){if(g.arrows<=0||!byId(g.mark)?.alive||g.round<=g.markRound)return;const t=byId(g.mark);g.arrows--;g.mark=null;deaths=eliminate([faction(t)==='village'?p.id:t.id],'tên Cung thủ');report=p.name+' (Cung thủ) bắn '+t.name+'.'}else{const t=byId(selected[0]);if(!t?.alive||t.id===p.id)return;if(r==='priest'){if(g.priestUsed)return;g.priestUsed=true;deaths=eliminate([isWolf(t)?t.id:p.id],'nước thánh');report=p.name+' (Linh mục) dùng nước thánh lên '+t.name+'.'}else if(r==='gunner'){if(g.bullets<=0||g.gunDay===g.round||g.round<2||g.lovers.includes(p.id)&&g.lovers.includes(t.id))return;g.bullets--;g.gunDay=g.round;deaths=eliminate([t.id],'súng Xạ thủ');report=p.name+' (Xạ thủ) bắn '+t.name+'.'}}g.publicReport.push(report);addLog(report);if(deaths.length){const msg='Bị loại: '+deaths.map(id=>byId(id).name+(g.settings.revealDeath?' ('+ROLES[byId(id).role].name+')':'')).join(', ')+'.';g.publicReport.push(msg);g.votes={};g.ballots={};}g.stage='day';secret=false;selected=[];if(!checkWin())save();render()}
function recountVotes(){const g=state.game;g.votes={};for(const p of alive()){const target=Number(g.ballots[p.id]);if(g.ballots[p.id]!=null&&g.ballots[p.id]!==''&&byId(target)?.alive){const weight=p.role==='mayor'&&g.mayorRevealed?2:1;g.votes[target]=(g.votes[target]||0)+weight}}}
function voteView(){const g=state.game;if(g.voteMode!=='ballots')return legacyVoteView();recountVotes();const ps=alive();return `<div class="eyebrow">Bỏ phiếu · Ngày ${g.round}</div><h1>Bỏ phiếu loại người</h1><p>Chọn lá phiếu của từng người theo kết quả giơ tay. Thị trưởng đã công khai có trọng số 2. Để Bỏ qua nếu người đó không bỏ phiếu.</p><div class="ballot-list">${ps.map(p=>`<label class="ballot-row"><span>${esc(p.name)}${p.role==='mayor'&&g.mayorRevealed?' <b>×2</b>':''}</span><select aria-label="Lá phiếu của ${esc(p.name)}" data-ballot="${p.id}"><option value="">Bỏ qua</option>${ps.map(t=>`<option value="${t.id}" ${String(g.ballots[p.id])===String(t.id)?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label>`).join('')}</div><div class="public-report"><h2>Kiểm phiếu</h2>${ps.map(p=>`<div class="tally-row"><span>${esc(p.name)}</span><b>${g.votes[p.id]||0}</b></div>`).join('')}</div><p class="hint">Hòa phiếu hoặc không có phiếu: không treo ai.</p><div class="actions"><button class="secondary" data-action="back-day">← Thảo luận tiếp</button><button class="primary" data-action="vote-confirm">Chốt phiếu →</button></div>`}

function legacyVoteView(){const g=state.game,cast=Object.values(g.votes).reduce((a,b)=>a+b,0);return `<div class="eyebrow">Bỏ phiếu · Ngày ${g.round}</div><h1>Bỏ phiếu loại người</h1><p>Cả nhóm giơ tay bỏ phiếu ngoài đời. Nhập tổng số phiếu từng người nhận được. Mỗi người còn sống có tối đa một phiếu; số chưa nhập được tính là bỏ qua.</p><div>${alive().map(p=>`<div class="vote-row">${avatar(p)}<span class="name">${esc(p.name)}</span><div class="stepper"><button data-action="vote-count" data-id="${p.id}" data-delta="-1" aria-label="Giảm phiếu cho ${esc(p.name)}" ${!(g.votes[p.id]>0)?'disabled':''}>−</button><span>${g.votes[p.id]||0}</span><button data-action="vote-count" data-id="${p.id}" data-delta="1" aria-label="Thêm phiếu cho ${esc(p.name)}" ${cast>=alive().length?'disabled':''}>+</button></div></div>`).join('')}</div><p class="hint">${cast} / ${alive().length} phiếu · ${alive().length-cast} bỏ qua · Hòa phiếu: không treo ai.</p><div class="actions"><button class="secondary" data-action="back-day">← Thảo luận tiếp</button><button class="primary" data-action="vote-confirm">Chốt phiếu →</button></div>`}
function voteOutcome(){const g=state.game,v=alive().map(p=>({id:p.id,votes:g.votes[p.id]||0})),max=Math.max(...v.map(x=>x.votes)),top=v.filter(x=>x.votes===max);return max>0&&top.length===1?top[0].id:null}
function resolveVote(){const g=state.game,id=voteOutcome();if(id!=null){const p=byId(id);if(p.role==='jester'){p.alive=false;g.winner='jester';g.stage='over';addLog(p.name+' (Chán đời) bị treo cổ và thắng riêng.');save();render();return}const dead=eliminate([id],'bỏ phiếu ngày '+g.round);g.dawn=[];g.afterHunter='vote';if(g.hunters.length){g.stage='hunter';secret=false;selected=[];save();render();return}toast(dead.map(x=>byId(x).name).join(', ')+' bị loại.')}else addLog('Ngày '+g.round+': hòa phiếu hoặc không có phiếu. Không ai bị treo.');if(!checkWin()){g.round++;beginNight()}else render()}
function formatTime(s){return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')}
function stopTimer(){if(timerRunning)timerLeft=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));timerRunning=false;clearInterval(timerInterval)}
function toggleTimer(){if(timerRunning)stopTimer();else{if(timerLeft<=0)timerLeft=state.game.settings.minutes*60;timerEnd=Date.now()+timerLeft*1000;timerRunning=true;timerInterval=setInterval(()=>{const t=Math.max(0,Math.ceil((timerEnd-Date.now())/1000)),el=document.getElementById('timer');if(el)el.textContent=formatTime(t);if(t===0){stopTimer();toast('Hết giờ thảo luận. Đến lượt bỏ phiếu!');if(page==='game')render()}},300)}render()}
function downloadOffline(){fetch('./Ma-Soi-Dem-Lang-Offline.html').then(r=>{if(!r.ok)throw Error();return r.blob()}).then(blob=>{const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Ma-Soi-Dem-Lang-Offline.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Đã tải bản HTML. Mở file bằng trình duyệt để chơi offline.');}).catch(()=>toast('Chưa tải được bản offline. Hãy kết nối mạng và thử lại.'))}
function moderatorBook(){modal.innerHTML=`<div class="dialog-head"><h2>Sổ quản trò · Bí mật</h2><button class="close" data-action="close" aria-label="Đóng">×</button></div><p class="hint">Chỉ quản trò được xem. Đóng sổ trước khi đưa máy cho người chơi.</p><div class="results-list">${state.game.players.map(p=>`<div><span class="role-symbol">${icon(p.role)}</span>${avatar(p)}<span><b>${esc(p.name)}</b><small>${ROLES[p.role].name}${p.initialRole&&p.initialRole!==p.role?' (ban đầu: '+ROLES[p.initialRole].name+')':''} · ${p.alive?'Còn sống':'Đã bị loại'}${state.game.lovers.includes(p.id)?' · ♥':''}</small></span></div>`).join('')}</div>`;modal.showModal()}
function veil(){secret=false;selected=[];nightResult=null;if(modal.open)modal.close();if('speechSynthesis'in window)speechSynthesis.cancel();stopCamera();if(page==='game')render()}
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;if(el.matches('.brand')){e.preventDefault();page='play';veil();render();window.scrollTo(0,0);return}if(el.dataset.page){secret=false;selected=[];nightResult=null;page=el.dataset.page;render();window.scrollTo(0,0);return}const a=el.dataset.action,g=state.game;switch(a){case 'add':if(state.players.length<24){let label=state.players.length+1;while(state.players.includes('Người chơi '+label))label++;state.players.push('Người chơi '+label);state.photos.push('');resizeSetup();render()}break;case 'remove':if(removeSetupPlayer(Number(el.dataset.index)))render();break;case 'role':if(changeRole(el.dataset.role,Number(el.dataset.delta)))render();break;case 'filter':roleFilter=el.dataset.value;libraryLimit=24;render();break;case 'preset':if(el.dataset.value!=='custom')choosePreset(el.dataset.value);else{state.preset='custom';save()}render();if(el.dataset.value!=='custom')closeSuggestions();break;case 'mode':if(el.dataset.value==='auto'&&needsModerator())break;state.settings.mode=el.dataset.value;save();render();break;case 'expand':expanded=!expanded;render();break;case 'settings':settings();break;case 'close':modal.close();if(page==='play')render();break;case 'start':if(g&&!['over','manual-over'].includes(g.stage))confirmBox('Bắt đầu ván mới?','Ván đang chơi sẽ được thay bằng ván mới.','start-confirm','Chia vai ván mới');else newGame();break;case 'start-confirm':modal.close();newGame();break;case 'resume':page='game';veil();if(g.stage==='day'&&timerLeft===0)timerLeft=g.settings.minutes*60;render();window.scrollTo(0,0);break;case 'exit':secret=false;selected=[];nightResult=null;page='play';render();window.scrollTo(0,0);break;case 'replay':newGame();break;case 'deal-open':if(page==='game'&&g?.stage==='deal'&&!secret&&document.getElementById('dealPrivacy')?.checked){secret=true;selected=[];nightResult=null;render()}break;case 'unlock':if(g?.stage==='deal')break;secret=true;selected=[];nightResult=null;render();break;case 'deal-next':secret=false;g.dealIndex++;if(g.dealIndex>=g.players.length)g.stage='ready';save();render();break;case 'begin-night':if(g.manual){startModeratorNight();break}beginNight();speak('Cả làng đi ngủ. '+roleName(g.queue[0])+', hãy thức dậy.');break;case 'veil':veil();break;case 'target':{const id=Number(el.dataset.id);if(el.dataset.multiple){if(selected.includes(id))selected=selected.filter(x=>x!==id);else if(selected.length<2)selected.push(id);else toast('Chỉ chọn hai người. Bấm vào người đã chọn để bỏ chọn.')}else selected=selected.includes(id)?[]:[id];render();break}case 'night-next':nextNight();if(g.stage==='night')speak(roleName(g.queue[g.nightIndex])+', hãy thức dậy.');break;case 'night-skip':if(g.queue[g.nightIndex]==='ext_junior_werewolf')g.juniorTarget=null;if(g.queue[g.nightIndex]==='hunter')g.hunterTarget=null;addLog('Đêm '+g.round+': '+ROLES[g.queue[g.nightIndex]].name+' bỏ qua kỹ năng.');nextNight();if(g.stage==='night')speak(roleName(g.queue[g.nightIndex])+', hãy thức dậy.');break;case 'night-confirm':handleNightConfirm();break;case 'seer-done':if(nightResult){addLog('Đêm '+g.round+': '+roleName(g.queue[g.nightIndex])+' xem '+nightResult.names+' · '+nightResult.title);nextNight();speakNext()}break;case 'witch-done':{const heal=document.getElementById('healChoice')?.checked;if(heal&&!g.healUsed&&g.night.wolf!=null){g.night.heal=true;g.healUsed=true;addLog('Đêm '+g.round+': Phù thủy dùng bình cứu.')}if(selected.length&&!g.poisonUsed){g.night.poison=selected[0];g.poisonUsed=true;addLog('Đêm '+g.round+': Phù thủy đầu độc '+byId(selected[0]).name+'.')}nextNight();speakNext();break}case 'day':if(!checkWin()){g.stage='day';timerLeft=g.settings.minutes*60;save()}render();break;case 'timer':toggleTimer();break;case 'timer-reset':stopTimer();timerLeft=g.settings.minutes*60;render();break;case 'vote':stopTimer();g.stage='vote';save();render();break;case 'back-day':g.stage='day';save();render();break;case 'powers':openPowers();break;case 'power-open':modal.close();g.powerRole=el.dataset.role;g.stage='power';secret=false;selected=[];save();render();window.scrollTo(0,0);break;case 'power-back':g.stage='day';secret=false;selected=[];save();render();break;case 'power-confirm':confirmBox('Dùng kỹ năng công khai?','Hành động sẽ công khai vai và có thể loại người ngay lập tức.','power-use','Dùng kỹ năng');break;case 'power-use':modal.close();useDayPower();break;case 'status-next':g.statusIndex=(g.statusIndex||0)+1;secret=false;if(g.statusIndex>=alive().length){nextNight();speakNext()}else{save();render()}break;case 'marksman-night-shoot':if(g.arrows>0&&byId(g.mark)?.alive&&g.round>g.markRound){g.night.marksmanShot=g.mark;g.arrows--;g.mark=null;addLog('Đêm '+g.round+': Cung thủ bắn mục tiêu đã đánh dấu.');nextNight();speakNext()}break;case 'vote-count':{const id=el.dataset.id,delta=Number(el.dataset.delta),sum=Object.values(g.votes).reduce((a,b)=>a+b,0);if(delta>0&&sum>=alive().length)break;g.votes[id]=Math.max(0,(g.votes[id]||0)+delta);save();render();break}case 'vote-confirm':{const id=voteOutcome();confirmBox('Chốt quyết định của làng?',id==null?'Hòa phiếu hoặc không có phiếu. Không ai bị treo cổ.':esc(byId(id).name)+' nhận nhiều phiếu nhất và sẽ bị treo cổ.','vote-resolve','Chốt kết quả');break}case 'vote-resolve':modal.close();resolveVote();break;case 'hunter-fire':if(selected.length!==1)break;{const dead=eliminate([selected[0]],'phát súng Thợ săn');g.dawn.push(...dead);g.hunterUsed=true;g.hunters.shift();toast(dead.map(x=>byId(x).name).join(', ')+' bị loại.');afterHunter();break}case 'hunter-skip':g.hunterUsed=true;g.hunters.shift();addLog('Thợ săn bỏ qua phát súng.');afterHunter();break;case 'moderator':confirmBox('Chỉ dành cho quản trò','Màn hình tiếp theo sẽ hiển thị toàn bộ vai. Đảm bảo không có người chơi nhìn thấy.','moderator-open','Tôi là quản trò');break;case 'moderator-open':modal.close();moderatorBook();break;}});
document.addEventListener('change',e=>{if(e.target.matches('[data-ballot]')){state.game.ballots[e.target.dataset.ballot]=e.target.value;recountVotes();save();render()}});
document.addEventListener('input',e=>{if(e.target.matches('[data-name]')){state.players[Number(e.target.dataset.name)]=e.target.value;save()}if(e.target.id==='healChoice'){state.game.night.heal=e.target.checked;save()}});
document.addEventListener('submit',e=>{if(e.target.id!=='settingsForm')return;e.preventDefault();const f=new FormData(e.target);state.settings={mode:needsModerator()?'moderator':f.get('mode'),minutes:Number(f.get('minutes')),revealDeath:f.has('revealDeath'),voice:f.has('voice')};save();modal.close();if(page!=='game')render();toast('Đã lưu thiết lập cho ván mới.');});
document.getElementById('settingsBtn').addEventListener('click',settings);
document.getElementById('downloadBtn').addEventListener('click',()=>{if(location.protocol==='file:'||document.documentElement.dataset.standalone==='true'){const a=document.createElement('a');a.href=location.href;a.download='Ma-Soi-Dem-Lang-Offline.html';a.click();return}downloadOffline()});
document.addEventListener('visibilitychange',()=>{if(document.hidden)veil()});
window.addEventListener('pagehide',()=>{secret=false;save()});
window.addEventListener('pageshow',e=>{if(e.persisted)veil()});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
if('serviceWorker'in navigator&&location.protocol==='https:'&&document.documentElement.dataset.standalone!=='true')navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{document.getElementById('offlineStatus').innerHTML='<b class="dot"></b> Đã lưu để chơi offline';}).catch(()=>{});
if(state.game?.stage==='day')timerLeft=state.game.settings.minutes*60;
render();

if ('serviceWorker' in navigator) {
  const hadController = !!navigator.serviceWorker.controller;
  navigator.serviceWorker.addEventListener('controllerchange', () => {
    if (!hadController || document.getElementById('reloadUpdate')) return;
    const button = document.createElement('button');
    button.id = 'reloadUpdate';
    button.className = 'secondary';
    button.textContent = 'Có bản mới · Tải lại';
    button.addEventListener('click', () => {
      if (!save()) return;
      veil();
      window.location.reload();
    });
    document.querySelector('footer')?.append(button);
  });
}

let cameraFacing='environment',cameraRequest=0;
function stopCamera(){cameraRequest++;if(cameraStream){cameraStream.getTracks().forEach(t=>t.stop());cameraStream=null}const video=document.getElementById('cameraVideo');if(video)video.srcObject=null}
function photoModal(){stopCamera();modal.innerHTML=`<div class="dialog-head"><h2>Ảnh ${esc(state.players[photoIndex])}</h2><button class="close" data-action="close" aria-label="Đóng">×</button></div><div class="photo-preview">${photoDraft?`<img src="${photoDraft}" alt="Ảnh xem trước">`:'<span>Chưa có ảnh</span>'}</div><p class="hint">Ảnh chỉ lưu trong trình duyệt trên thiết bị này. Ảnh được cắt vuông và thu nhỏ để dùng offline.</p><div class="actions"><button class="secondary" data-action="camera-start">Chụp bằng camera</button><button class="secondary" data-action="photo-file">Chọn ảnh có sẵn</button><button class="text-btn" data-action="photo-native">Mở camera điện thoại</button><button class="text-btn" data-action="photo-remove">Bỏ ảnh</button></div><input type="file" id="photoFile" accept="image/jpeg,image/png,image/webp,image/gif,image/avif,image/heic,image/heif" hidden><input type="file" id="photoNative" accept="image/*" capture="environment" hidden><div class="actions"><button class="primary" data-action="photo-save">Dùng ảnh</button></div>`;if(!modal.open)modal.showModal()}
function photoFromSource(source,w,h){if(!w||!h||w*h>60000000)throw Error('Ảnh quá lớn hoặc chưa sẵn sàng.');const canvas=document.createElement('canvas');canvas.width=192;canvas.height=192;const context=canvas.getContext('2d'),side=Math.min(w,h);context.drawImage(source,(w-side)/2,(h-side)/2,side,side,0,0,192,192);return canvas.toDataURL('image/jpeg',.78)}
async function loadPhotoFile(file){if(!file)return;if(file.size>15*1024*1024)return toast('Ảnh tối đa 15 MB.');if(file.type==='image/svg+xml'||!file.type.startsWith('image/'))return toast('Chọn ảnh JPEG, PNG, WebP hoặc ảnh chụp thông thường.');const url=URL.createObjectURL(file);try{const im=new Image();await new Promise((resolve,reject)=>{im.onload=resolve;im.onerror=reject;im.src=url});photoDraft=photoFromSource(im,im.naturalWidth,im.naturalHeight);photoModal()}catch(e){toast('Không mở được ảnh này. Thử JPEG hoặc PNG.')}finally{URL.revokeObjectURL(url)}}
async function startCamera(facing=cameraFacing){
 if(!navigator.mediaDevices?.getUserMedia){toast('Trình duyệt chưa mở được camera trực tiếp. Dùng Mở camera điện thoại hoặc Chọn ảnh.');return}
 stopCamera();const request=cameraRequest;cameraFacing=facing;
 modal.innerHTML=`<div class="dialog-head"><h2>Đang mở camera…</h2><button class="close" data-action="close" aria-label="Đóng">×</button></div><p role="status">Đang mở ${facing==='environment'?'camera sau':'camera trước'}. Cho phép truy cập camera nếu trình duyệt hỏi.</p><button class="secondary" data-action="camera-back">Quay lại</button>`;
 try{
 let stream;try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{exact:facing},width:{ideal:640},height:{ideal:640}},audio:false})}catch(e){if(request!==cameraRequest)return;if(!['OverconstrainedError','NotFoundError'].includes(e?.name))throw e;stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:facing},width:{ideal:640},height:{ideal:640}},audio:false})}
 if(request!==cameraRequest||!modal.open||photoIndex===null){stream.getTracks().forEach(t=>t.stop());return}
 cameraStream=stream;const actual=stream.getVideoTracks()[0]?.getSettings?.().facingMode;if(['user','environment'].includes(actual))cameraFacing=actual;
 modal.innerHTML=`<div class="dialog-head"><h2>Chụp ảnh người chơi</h2><button class="close" data-action="close" aria-label="Đóng">×</button></div><video id="cameraVideo" autoplay muted playsinline></video><p class="hint">${actual==='environment'?'Camera sau':actual==='user'?'Camera trước':'Camera đang dùng'} · Đưa khuôn mặt vào giữa khung. Camera tắt sau khi chụp hoặc đóng.</p><div class="actions"><button class="secondary" data-action="camera-switch">Đổi camera trước / sau</button><button class="secondary" data-action="camera-back">Quay lại</button><button class="primary" data-action="camera-capture">Chụp ảnh</button><button class="text-btn" data-action="photo-native">Mở camera điện thoại</button></div>`;
 const video=document.getElementById('cameraVideo');video.srcObject=stream;await video.play();
 }catch(e){if(request!==cameraRequest)return;stopCamera();photoModal();toast(e?.name==='NotAllowedError'?'Chưa được cấp quyền camera. Bro có thể chọn ảnh có sẵn.':'Không mở được camera đã chọn. Thử Mở camera điện thoại hoặc chọn ảnh.')}
}

function setPlayerPhoto(index,photo){const clean=cleanPhoto(photo);state.photos[index]=clean;const p=state.game?.players.find(p=>p.id===index&&p.name===state.players[index]);if(p)p.photo=clean;return save()}
function customPoolModal(){modal.innerHTML=`<div class="dialog-head"><h2>Danh sách rút tùy chọn</h2><button class="close" data-action="close" aria-label="Đóng">×</button></div><label class="field"><span>Tìm vai để đưa vào nhóm rút</span><input id="poolSearch" placeholder="Tên Việt hoặc Anh…" autocomplete="off"></label><p class="hint">Chỉ chọn vai đã có luật; vai cần thỏa thuận riêng không nằm trong nhóm rút. Lựa chọn lưu ngay, ô ngẫu nhiên không phải nhân vật riêng.</p><div id="poolResults" class="pool-results">${poolRows('')}</div>`;if(!modal.open)modal.showModal()}
function poolRows(query){return Object.entries(ROLES).filter(([k,r])=>!r.random&&!r.houseRule&&roleMatches(k,query,'all')).map(([k,r])=>`<label class="pool-row"><input type="checkbox" data-pool-role="${k}" ${state.customPool.includes(k)?'checked':''}><span>${r.name}<small>${r.english} · ${roleBadge(k)}</small></span></label>`).join('')||'<p>Không tìm thấy vai.</p>'}
function ensureModerator(g){if(!g)return;g.mod??={phase:'night',step:0,queue:[],records:[],snapshots:[],pending:[],report:[],result:'',winnerIds:[]};g.players.forEach(p=>{p.modTeam??=ROLES[p.role]?.team||'Phe riêng';p.modVotes??=1;p.modBlocked??=false;p.modMuted??=false;p.modProtected??=false;p.modNotes??='';p.modCounter??=0;p.modDeadVotes??=false});}
function captureModState(g) {
  return {label:`${g.mod.phase==='night'?'Đêm':'Ngày'} ${g.round}`,round:g.round,phase:g.mod.phase,players:g.players.map(({photo,...p})=>structuredClone(p)),records:structuredClone(g.mod.records),ballots:structuredClone(g.ballots),pending:[...g.mod.pending],report:[...g.mod.report],lovers:[...g.lovers],hunterTarget:g.hunterTarget,hunterUsed:g.hunterUsed,queue:[...g.mod.queue],step:g.mod.step,skills:g.skills?structuredClone(g.skills):null};
}

function modSnapshot() {
  const g = state.game;
  ensureModerator(g);
  g.mod.snapshots.push(captureModState(g));
  if (g.mod.snapshots.length > 12) g.mod.snapshots.shift();
}

function startModeratorNight(){const g=state.game;ensureModerator(g);if(g.stage==='ready'){g.stage='moderator';g.mod.phase='night'}else{if(typeof skillAdvance==='function')skillAdvance();g.round++;g.mod.phase='night'}g.mod.report=[];g.mod.pending=[];g.mod.step=0;g.mod.queue=[...new Set(g.players.flatMap(p=>[p.initialRole,p.role]))].filter(k=>ROLES[k]&&(['night','both'].includes(ROLES[k].phase)||g.round===1&&ROLES[k].phase==='setup')).sort((a,b)=>(a==='hunter'?-100:ROLES[a].phase==='setup'?-50:ROLES[a].group==='wolf'?10:0)-(b==='hunter'?-100:ROLES[b].phase==='setup'?-50:ROLES[b].group==='wolf'?10:0));g.ballots={};g.votes={};secret=false;selected=[];modSnapshot();addLog('Đêm '+g.round+' · quản trò điều khiển.');save();render();window.scrollTo(0,0)}
function moderatorView(){const g=state.game;ensureModerator(g);const m=g.mod,header=`<div class="game-wrap moderator-wrap"><div class="game-top"><p>${g.stage==='manual-over'?'KẾT THÚC VÁN':'QUẢN TRÒ HỖ TRỢ · '+(m.phase==='night'?'ĐÊM ':'NGÀY ')+g.round}</p><div>${g.stage!=='manual-over'?'<button class="text-btn" data-action="mod-public">Màn hình chung</button>':''}<button class="text-btn" data-action="exit">Về bàn chơi</button></div></div>`;
if(g.stage==='manual-over')return header+`<section class="game-stage"><span class="large-symbol">${icon('sun')}</span><h1>${esc(m.result||'Ván đã kết thúc.')}</h1><p>Kết quả do quản trò xác nhận.</p><div class="results-list">${g.players.map(p=>`<div>${avatar(p)}<span><b>${esc(p.name)} ${m.winnerIds.includes(p.id)?'★':''}</b><small>${ROLES[p.role].name} · ${esc(p.modTeam)} · ${p.alive?'Còn sống':'Đã bị loại'}</small></span></div>`).join('')}</div><details class="log"><summary>Nhật ký quản trò</summary><ol>${g.log.map(s=>`<li>${esc(s)}</li>`).join('')}</ol></details><div class="actions"><button class="secondary" data-action="exit">Về bàn chơi</button>${window.roomUI?.isBoard()?'':'<button class="primary" data-action="replay">Chơi lại cùng nhóm</button>'}</div></section></div>`;
if(g.stage==='mod-public')return header+`<section class="game-stage"><span class="large-symbol">${icon(m.phase==='night'?'moon':'sun')}</span><h1>${m.phase==='night'?'Cả làng nhắm mắt.':'Cả làng thức dậy.'}</h1><p>${m.phase==='night'?'Quản trò lần lượt gọi các vai. Chỉ người được gọi mở mắt.':'Thảo luận và bỏ phiếu theo hướng dẫn của quản trò.'}</p>${m.report.length?`<div class="public-report">${m.report.map(t=>`<p>${esc(t)}</p>`).join('')}</div>`:''}<div class="alive-strip">${g.players.filter(p=>p.alive).map(p=>`<span>${esc(p.name)}</span>`).join('')}</div><button class="primary" data-action="mod-private">Quay lại bảng quản trò</button></section></div>`;
if(!secret)return header+`<section class="game-stage">${gate('Chỉ quản trò cầm máy.','Bảng tiếp theo hiển thị toàn bộ vai và thông tin bí mật. Mọi người khác tránh nhìn màn hình.','Tôi là quản trò')}</section></div>`;
const current=m.queue[m.step],voters=g.players.filter(p=>p.alive||p.modDeadVotes);return header+`<div class="assist-note"><strong>Quản trò tự xử lý kỹ năng và xét thắng.</strong> Bảng hỗ trợ ghi lựa chọn, đổi vai, loại/hồi sinh và tính phiếu. Không tự suy diễn tương tác của bộ vai mở rộng.</div><div class="mod-toolbar"><button class="secondary" data-action="mod-undo" ${m.snapshots.length?'':'disabled'}>Hoàn tác mốc gần nhất</button><button class="secondary" data-action="mod-finish">Công bố kết quả</button><button class="secondary" data-action="mod-public">Che vai · màn hình chung</button></div><section class="panel mod-night-guide"><div class="panel-head"><h2>${m.phase==='night'?'Lời gọi & kỹ năng đêm':'Điều khiển ban ngày'}</h2><span>${m.phase==='night'?Math.min(m.step+1,m.queue.length)+' / '+m.queue.length:'Ngày '+g.round}</span></div><div class="panel-body">${m.phase==='night'?current?`<h3>${current==='ext_little_girl'?'Cô bé · nhắc riêng quản trò':ROLES[current].name+', hãy thức dậy.'}</h3><p class="english-name">${current==='ext_little_girl'?'Không gọi riêng. Chỉ nhìn lén trong lượt Sói.':ROLES[current].english+' · vẫn gọi sau khi vai đã chết'}</p><p>${ROLES[current].desc}</p>${g.houseRules[current]?`<p class="assist-note">Luật nhóm: ${esc(g.houseRules[current])}</p>`:''}<div class="target-guide">${g.players.filter(p=>p.initialRole===current||p.role===current).map(p=>`<span>${avatar(p)}${esc(p.name)} · ${p.alive?'còn sống':'đã bị loại'}</span>`).join('')}</div><label class="field"><span>Ghi lựa chọn / hiệu ứng / thời hạn</span><textarea id="modNightNote" rows="2" maxlength="1500" placeholder="Ví dụ: bảo vệ Minh đêm 2; 1 lượt còn lại…">${esc(m.draft||'')}</textarea></label><label class="field"><span>${current==='hunter'?'Dấu Thợ săn (tự bắn khi bị loại)':'Mục tiêu ghi nhận (không tự áp dụng kỹ năng)'}</span><select id="modNightTarget"><option value="">Không chọn</option>${g.players.filter(p=>p.alive&&(current!=='hunter'||p.role!=='hunter')).map(p=>`<option value="${p.id}" ${String(m.draftTarget)===String(p.id)?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><div class="actions"><button class="secondary" data-action="mod-prev" ${m.step?'':'disabled'}>← Vai trước</button><button class="primary" data-action="mod-next">Lưu lượt & gọi vai sau →</button></div>`:'<p>Đã gọi hết lượt. Kiểm tra các hiệu ứng, người bị loại và chuyển sang bình minh.</p>':`<p>Dùng hồ sơ từng người để xử lý kỹ năng công khai, chỉnh số phiếu, cấm nói hoặc cấm kỹ năng.</p><button class="secondary" data-action="mod-votes">Mở bảng bỏ phiếu</button>`}<div class="actions">${m.phase==='night'?'<button class="primary" data-action="mod-dawn">Xác nhận bình minh →</button>':'<button class="primary" data-action="mod-night">Bắt đầu đêm kế tiếp →</button>'}</div></div></section><section class="mod-player-grid">${g.players.map(p=>`<button class="mod-player ${p.alive?'':'dead'}" data-action="mod-player" data-id="${p.id}">${avatar(p,true)}<span><b>${esc(p.name)}</b><strong>${ROLES[p.role].name}</strong><small>${esc(p.modTeam)} · ${p.alive?'Còn sống':'Đã bị loại'} · phiếu ×${p.modVotes}${p.modDeadVotes?' · được bỏ phiếu khi chết':''}</small><small>${p.modBlocked?'Khóa kỹ năng · ':''}${p.modMuted?'Cấm nói · ':''}${p.modProtected?'Có bảo vệ · ':''}${p.modCounter?'Điểm/lượt: '+p.modCounter:''}</small>${p.modNotes?`<small>${esc(p.modNotes.slice(0,100))}</small>`:''}</span></button>`).join('')}</section><details class="log"><summary>Ghi nhận kỹ năng (${m.records.length})</summary><ol>${m.records.slice(-30).map(r=>`<li>${esc(r)}</li>`).join('')}</ol></details></div>`}
function modOptions(query,current){return Object.entries(ROLES).filter(([k,r])=>!r.random&&roleMatches(k,query,'all')).map(([k,r])=>`<option value="${k}" ${k===current?'selected':''}>${r.name} · ${r.english}</option>`).join('')}
let modPlayerId=null;
function showModPlayer(id){const g=state.game,p=byId(id);modPlayerId=id;modal.innerHTML=`<div class="dialog-head"><h2>${esc(p.name)}</h2><button class="close" data-action="close" aria-label="Đóng">×</button></div><div class="mod-profile">${avatar(p,true)}<p>${ROLES[p.role].name}<br><small>${esc(p.modTeam)} · ${p.alive?'Còn sống':'Đã bị loại'}</small></p></div><form id="modPlayerForm"><label class="field"><span>Tìm vai để đổi</span><input id="modRoleSearch" placeholder="Tên Việt hoặc Anh…" autocomplete="off"></label><label class="field"><span>Vai hiện tại</span><select id="modRole" name="role">${modOptions('',p.role)}</select></label><label class="field"><span>Phe / nhóm thắng hiện tại</span><input name="team" value="${esc(p.modTeam)}" maxlength="60" required></label><div class="mod-form-grid"><label class="field"><span>Trọng số lá phiếu</span><input name="weight" type="number" min="0" max="20" value="${p.modVotes}"></label><label class="field"><span>Điểm / lượt kỹ năng</span><input name="counter" type="number" min="0" max="99" value="${p.modCounter}"></label></div><label class="check"><input type="checkbox" name="blocked" ${p.modBlocked?'checked':''}><span>Khóa kỹ năng</span></label><label class="check"><input type="checkbox" name="muted" ${p.modMuted?'checked':''}><span>Cấm nói</span></label><label class="check"><input type="checkbox" name="protected" ${p.modProtected?'checked':''}><span>Đang có bảo vệ</span></label><label class="check"><input type="checkbox" name="deadVotes" ${p.modDeadVotes?'checked':''}><span>Cho bỏ phiếu dù đã chết (ví dụ: Sói ma)</span></label><label class="field"><span>Ghi chú & thời hạn hiệu ứng</span><textarea name="notes" maxlength="1500" rows="3">${esc(p.modNotes)}</textarea></label><div class="actions"><button class="primary" type="submit">Lưu hồ sơ</button><button class="secondary" type="button" data-action="mod-alive-confirm" data-id="${p.id}">${p.alive?'Loại người này':'Hồi sinh người này'}</button><button class="text-btn" type="button" data-action="mod-role-info" data-role="${p.role}">Xem kỹ năng vai</button></div></form>`;modal.showModal()}
function modSetAlive(id,value){const g=state.game;ensureModerator(g);modSnapshot();const pending=[id],changed=[];while(pending.length){const p=byId(pending.shift());if(!p||p.alive===value)continue;p.alive=value;changed.push(p.id);if(!value&&p.role==='hunter'&&!g.hunterUsed){g.hunterUsed=true;if(g.hunterTarget!=null&&byId(g.hunterTarget)?.alive)pending.push(g.hunterTarget)}}if(!value)g.mod.pending.push(...changed.filter(id=>!g.mod.pending.includes(id)));else g.mod.pending=g.mod.pending.filter(id=>!changed.includes(id));const report=changed.map(id=>byId(id).name).join(', ')+' '+(value?'được hồi sinh.':'bị loại.');g.mod.records.push(report);addLog(report);g.ballots={};g.votes={};save();return changed}
function showModVotes(){const g=state.game,ps=g.players.filter(p=>p.alive||p.modDeadVotes);modal.innerHTML=`<div class="dialog-head"><h2>Phiếu do quản trò nhập</h2><button class="close" data-action="close" aria-label="Đóng">×</button></div><p class="hint">Máy tính tổng theo trọng số. Quản trò tự xét miễn treo, phiếu giả, phe riêng và các hiệu ứng khác trước khi loại người.</p><div class="ballot-list">${ps.map(p=>`<label class="ballot-row"><span>${esc(p.name)} ×${typeof skillVotes==='function'?skillVotes(p):p.modVotes}${p.alive?'':' · đã chết'}</span><select data-mod-ballot="${p.id}" aria-label="Phiếu quản trò của ${esc(p.name)}"><option value="">Bỏ qua</option>${g.players.filter(p=>p.alive).map(t=>`<option value="${t.id}" ${String(g.ballots[p.id])===String(t.id)?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label>`).join('')}</div><div id="modTally">${modTallyView()}</div>`;modal.showModal()}
function modTally(){const g=state.game,tally={};g.players.filter(p=>p.alive||p.modDeadVotes).forEach(p=>{const raw=g.ballots[p.id],id=Number(raw);if(raw!=null&&raw!==''&&byId(id)?.alive)tally[id]=(tally[id]||0)+Math.max(0,Math.min(20,p.modVotes))});return tally}
function modTallyView(){const tally=modTally();return `<div class="public-report"><h3>Kiểm phiếu</h3>${state.game.players.filter(p=>p.alive).map(p=>`<div class="tally-row"><span>${esc(p.name)}</span><b>${tally[p.id]||0}</b></div>`).join('')}</div>`}
function showModFinish(){const g=state.game;modal.innerHTML=`<div class="dialog-head"><h2>Công bố kết quả</h2><button class="close" data-action="close" aria-label="Đóng">×</button></div><form id="modFinishForm"><label class="field"><span>Kết quả do quản trò xác nhận</span><input name="result" placeholder="Ví dụ: Phe Làng chiến thắng" maxlength="160" required></label><p class="hint">${window.roomUI?.isBoard()?'Chọn tất cả người thắng, kể cả người đã bị loại nhưng thắng cùng phe. Mỗi người được cộng 1 trận thắng. Với ván hòa, đánh dấu Ván hòa.':'Chọn người thắng. Có thể chọn nhiều phe hoặc người thắng kèm.'}</p><div class="pool-results">${g.players.map(p=>`<label class="pool-row"><input type="checkbox" name="winner" value="${p.id}"><span>${esc(p.name)}<small>${ROLES[p.role].name}</small></span></label>`).join('')}</div>${window.roomUI?.isBoard()?'<label class="pool-row"><input type="checkbox" name="draw"><span>Ván hòa</span></label>':''}<div class="actions"><button class="primary" type="submit">Kết thúc & công khai toàn bộ vai</button></div></form>`;modal.showModal()}
function restoreModState(g, snapshot) {
  const m = g.mod;
  const photos=new Map(g.players.map(p=>[p.id,p.photo]));if(snapshot.skills)g.skills=structuredClone(snapshot.skills);else delete g.skills;g.players=snapshot.players.map(p=>({...structuredClone(p),photo:photos.get(p.id)||''}));g.round=snapshot.round;m.phase=snapshot.phase;m.records=structuredClone(snapshot.records);g.ballots=structuredClone(snapshot.ballots);m.pending=[...snapshot.pending];m.report=[...snapshot.report];g.lovers=[...snapshot.lovers];g.hunterTarget=snapshot.hunterTarget;g.hunterUsed=snapshot.hunterUsed;m.queue=[...snapshot.queue];m.step=snapshot.step;g.stage='moderator';g.votes={};
}

function restoreModSnapshot() {
  const g = state.game;
  const snapshot = g.mod.snapshots.pop();
  if (!snapshot) return false;
  restoreModState(g, snapshot);
  addLog('Quản trò hoàn tác về ' + snapshot.label + '.');
  save();
  return true;
}

// Catalog, local photos and moderator-assisted play controls.
modal.addEventListener('close',()=>{stopCamera();photoIndex=null;photoDraft=''});
document.addEventListener('click',async e=>{const el=e.target.closest('button');if(!el)return;const a=el.dataset.action,g=state.game;switch(a){
case 'dismiss-adjustment':state.setupAdjustment='';save();render();break;
case 'fill-villagers':{const gap=state.players.length-totalRoles();if(gap>0){rememberRoleSetup();state.roles.villager+=gap;state.preset='custom';save();render()}break}
case 'remove-with-role':if(removeSetupPlayer(Number(el.dataset.index),el.dataset.role)){modal.close();render()}break;
case 'voice-preview':speak('Cả làng nhắm mắt. Mời bầy Sói thức dậy.',true);break;
case 'deal-role-info':showDealtRoleInfo();break;
case 'role-info':showRoleInfo(el.dataset.role);break;
case 'picker-more': {
  const results = document.getElementById('pickerResults');
  const list = results.querySelector('.catalog-scroll');
  const more = results.querySelector('[data-action="picker-more"]');
  const scrollTop = list.scrollTop;
  const shown = list.children.length;
  pickerLimit += 20;
  const template = document.createElement('template');
  template.innerHTML = pickerRows();
  const newRows = Array.from(template.content.querySelector('.catalog-scroll').children).slice(shown);
  list.append(...newRows);
  if (!template.content.querySelector('[data-action="picker-more"]')) {
    if (document.activeElement === more) newRows[0]?.querySelector('.role-title')?.focus({preventScroll:true});
    more.remove();
  }
  list.scrollTop = scrollTop;
  break;
}
case 'undo-setup':if(undoRoleSetup())render();break;
case 'picker-reset':resetRoleSearch();render();document.getElementById('roleSearch')?.focus();break;
case 'library-reset':resetRoleSearch(true);render();document.getElementById('librarySearch')?.focus();break;
case 'picker-clear':pickerQuery='';pickerLimit=20;render();document.getElementById('roleSearch')?.focus();break;
case 'library-more':libraryLimit+=24;document.getElementById('libraryResults').innerHTML=libraryCards();break;
case 'library-clear':libraryQuery='';libraryLimit=24;render();document.getElementById('librarySearch')?.focus();break;
case 'custom-pool':modal.close();customPoolModal();break;
case 'photo-open':photoIndex=Number(el.dataset.index);photoDraft=cleanPhoto(state.photos[photoIndex]);photoModal();break;
case 'photo-file':document.getElementById('photoFile').click();break;
case 'photo-native':if(!document.getElementById('photoNative'))photoModal();document.getElementById('photoNative').click();break;
case 'photo-remove':photoDraft='';photoModal();break;
case 'photo-save':if(photoIndex!==null){const saved=setPlayerPhoto(photoIndex,photoDraft);modal.close();render();if(saved)toast('Đã lưu ảnh trên thiết bị.')}break;
case 'camera-start':await startCamera();break;
case 'camera-switch':await startCamera(cameraFacing==='environment'?'user':'environment');break;
case 'camera-capture':try{const v=document.getElementById('cameraVideo');photoDraft=photoFromSource(v,v.videoWidth,v.videoHeight);photoModal()}catch(e){toast('Chờ camera sẵn sàng rồi chụp lại.')}break;
case 'camera-back':photoModal();break;
case 'mod-public':if(g?.manual){g.stage='mod-public';secret=false;save();render()}break;
case 'mod-private':if(g?.manual){g.stage='moderator';secret=false;render()}break;
case 'mod-player':if(g?.manual&&secret)showModPlayer(Number(el.dataset.id));break;
case 'mod-role-info':modal.close();showRoleInfo(el.dataset.role);break;
case 'mod-alive-confirm':{if(!g?.manual||!secret)break;const p=byId(Number(el.dataset.id));modal.close();confirmBox(p.alive?'Loại '+esc(p.name)+'?':'Hồi sinh '+esc(p.name)+'?',p.alive?'Quản trò đã kiểm tra bảo vệ, đổi phe, cái chết liên kết và điều kiện đặc biệt. Dấu Thợ săn được xử lý tự động nếu đã đặt.':'Người này sẽ được đưa lại vào danh sách sống. Quản trò tự kiểm tra vai và kỹ năng sau hồi sinh.','mod-alive-apply',p.alive?'Xác nhận loại':'Xác nhận hồi sinh');modPlayerId=p.id;break}
case 'mod-alive-apply':if(g?.manual&&secret){const p=byId(modPlayerId);modSetAlive(p.id,!p.alive);modal.close();render()}break;
case 'mod-next':if(g?.manual&&secret){const m=g.mod,k=m.queue[m.step];if(!k)break;modSnapshot();const target=m.draftTarget!=null&&m.draftTarget!==''?Number(m.draftTarget):null;if(k==='hunter'&&g.players.some(p=>p.alive&&p.role==='hunter')){if(target!==null&&byId(target)?.role==='hunter'){toast('Thợ săn chọn người khác.');break}g.hunterTarget=target}const entry=`Đêm ${g.round} · ${ROLES[k].name}: ${target!=null?byId(target)?.name+' · ':''}${m.draft||'không ghi hành động'}`;m.records.push(entry);addLog(entry);m.step++;m.draft='';m.draftTarget='';save();render()}break;
case 'mod-prev':if(g?.manual&&secret&&g.mod.step>0){g.mod.step--;g.mod.draft='';g.mod.draftTarget='';save();render()}break;
case 'mod-dawn':if(g?.manual&&secret){modal.innerHTML=`<div class="dialog-head"><h2>Thông báo bình minh</h2><button class="close" data-action="close" aria-label="Đóng">×</button></div><form id="modDawnForm"><label class="field"><span>Nội dung cả làng được xem</span><textarea name="report" rows="5" maxlength="1500">${esc(g.mod.pending.length?'Bị loại: '+g.mod.pending.map(id=>byId(id).name+(g.settings.revealDeath?' ('+ROLES[byId(id).role].name+')':'')).join(', ')+'.':'Không có ai bị loại đêm qua.')}</textarea></label><p class="hint">Quản trò sửa nội dung nếu có vai làm giả thông báo hoặc hiệu ứng che vai.</p><div class="actions"><button class="primary" type="submit">Bình minh · hiện màn hình chung</button></div></form>`;modal.showModal()}break;
case 'mod-night':if(g?.manual&&secret)confirmBox('Bắt đầu đêm kế tiếp?','Kiểm tra hết kỹ năng, phiếu và điều kiện thắng trước khi chuyển đêm.','mod-night-apply','Sang đêm kế tiếp');break;
case 'mod-night-apply':modal.close();startModeratorNight();break;
case 'mod-votes':if(g?.manual&&secret)showModVotes();break;
case 'mod-undo':if(g?.manual&&secret)confirmBox('Hoàn tác mốc gần nhất?','Phục hồi vai, trạng thái, điểm, phiếu và ghi nhận tại mốc đã lưu. Quản trò tự quyết định những chuyển phe nào cần giữ lại.','mod-undo-apply','Phục hồi mốc');break;
case 'mod-undo-apply':modal.close();restoreModSnapshot();render();break;
case 'mod-finish':if(g?.manual&&secret)showModFinish();break;
}});
document.addEventListener('input',e=>{const t=e.target;if(t.matches('[data-role-search]')){pickerQuery=t.value;refreshPickerResults()}if(t.matches('[data-library-search]')){libraryQuery=t.value;libraryLimit=24;document.getElementById('libraryResults').innerHTML=libraryCards()}if(t.matches('[data-house-rule]')){state.houseRules[t.dataset.houseRule]=t.value;save()}if(t.id==='poolSearch')document.getElementById('poolResults').innerHTML=poolRows(t.value);if(t.id==='modRoleSearch'){const select=document.getElementById('modRole'),current=select.value;select.innerHTML=modOptions(t.value,current)}if(t.id==='modNightNote'&&state.game?.manual){state.game.mod.draft=t.value;save()}});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='groupExperience'){state.experience=t.value;save();render()}if(t.id==='presetSelect'){if(t.value==='custom'){state.preset='custom';save()}else choosePreset(t.value);render();if(t.value!=='custom')closeSuggestions()}if(t.id==='roleFilter'){pickerFilter=t.value;refreshPickerResults()}if(t.id==='photoFile'||t.id==='photoNative')loadPhotoFile(t.files[0]);if(t.matches('[data-pool-role]')){const k=t.dataset.poolRole;state.customPool=t.checked?[...new Set([...state.customPool,k])]:state.customPool.filter(id=>id!==k);save()}if(t.id==='modRole'&&ROLES[t.value])t.form.elements.team.value=ROLES[t.value].team;if(t.id==='modNightTarget'&&state.game?.manual){state.game.mod.draftTarget=t.value;save()}if(t.matches('[data-mod-ballot]')&&state.game?.manual){state.game.ballots[t.dataset.modBallot]=t.value;save();document.getElementById('modTally').innerHTML=modTallyView()}});
document.addEventListener('submit',e=>{const f=e.target,g=state.game;if(f.id==='modPlayerForm'){e.preventDefault();if(!g?.manual||!secret)return;const data=new FormData(f),p=byId(modPlayerId),k=data.get('role');if(!ROLES[k]||ROLES[k].random)return toast('Chọn một vai cụ thể.');modSnapshot();p.role=k;p.modTeam=String(data.get('team')||ROLES[k].team).slice(0,60);p.modVotes=Math.max(0,Math.min(20,Number(data.get('weight'))||0));p.modCounter=Math.max(0,Math.min(99,Number(data.get('counter'))||0));p.modBlocked=data.has('blocked');p.modMuted=data.has('muted');p.modProtected=data.has('protected');p.modDeadVotes=data.has('deadVotes');p.modNotes=String(data.get('notes')||'').slice(0,1500);addLog('Quản trò cập nhật hồ sơ '+p.name+'.');save();modal.close();render()}if(f.id==='modDawnForm'){e.preventDefault();if(!g?.manual||!secret)return;const data=new FormData(f);modSnapshot();g.mod.report=[String(data.get('report')||'').slice(0,1500)];g.mod.phase='day';if(typeof skillAdvance==='function')skillAdvance();g.mod.pending=[];g.ballots={};g.votes={};if(typeof captureDayStart==='function')captureDayStart(g);g.stage='mod-public';secret=false;save();modal.close();render()}if(f.id==='modFinishForm'){e.preventDefault();if(!g?.manual||!secret)return;const data=new FormData(f);g.mod.result=String(data.get('result')||'').trim().slice(0,160);if(!g.mod.result)return;const winners=data.getAll('winner').map(Number).filter(id=>!!byId(id));if(window.roomUI?.isBoard()&&data.has('draw')===!!winners.length)return toast(winners.length?'Bỏ chọn Ván hòa nếu đã chọn người thắng.':'Chọn người thắng hoặc đánh dấu Ván hòa.');g.mod.winnerIds=winners;g.stage='manual-over';addLog('Kết quả quản trò: '+g.mod.result);secret=false;save();modal.close();render()}});

modal.addEventListener('close',()=>{if(page==='play')render()});

document.addEventListener('toggle',e=>{if(e.target.id==='setupSuggestions'&&e.target.isConnected)suggestionsOpen=e.target.open},true);

// Versioned, local-only deck storage and reviewed backup import.
let pendingBackup=null;
function safeTree(value,depth=0){if(depth>30)throw Error('Dữ liệu lồng quá sâu.');if(value&&typeof value==='object'){for(const k of Object.keys(value)){if(['__proto__','prototype','constructor'].includes(k))throw Error('Tệp chứa khóa không hợp lệ.');safeTree(value[k],depth+1)}}}
function validRoles(raw,n,exact=true){if(!raw||typeof raw!=='object'||Array.isArray(raw))throw Error('Thiếu bộ vai.');const roles=Object.fromEntries(Object.keys(ROLES).map(k=>[k,0]));for(const[k,v]of Object.entries(raw)){if(!ROLES[k]||!Number.isInteger(v)||v<0||v>roleLimit(k))throw Error('Số lượng vai không hợp lệ.');roles[k]=v}const total=Object.values(roles).reduce((a,b)=>a+b,0);if(total>n||exact&&total!==n)throw Error('Số vai không khớp số người.');return roles}
function validSettings(raw={}){if(!['auto','moderator'].includes(raw.mode)||![1,2,3,4,5,7,10].includes(raw.minutes)||typeof raw.voice!=='boolean'||typeof raw.revealDeath!=='boolean')throw Error('Thiết lập không hợp lệ.');return {mode:raw.mode,minutes:raw.minutes,voice:raw.voice,revealDeath:raw.revealDeath}}
function validHouseRules(raw={}){if(!raw||typeof raw!=='object'||Array.isArray(raw))throw Error('Luật nhóm không hợp lệ.');const out={};for(const[k,v]of Object.entries(raw)){if(!ROLES[k]||typeof v!=='string'||v.length>1500)throw Error('Luật nhóm không hợp lệ.');out[k]=v}return out}
function validPool(raw=[]){if(!Array.isArray(raw)||raw.length>150||raw.some(k=>!ROLES[k]||ROLES[k].random||ROLES[k].houseRule))throw Error('Danh sách rút không hợp lệ.');return [...new Set(raw)]}
function validSavedDeck(raw){if(!raw||typeof raw.id!=='string'||!/^[a-zA-Z0-9_-]{1,80}$/.test(raw.id)||typeof raw.name!=='string'||!raw.name.trim()||raw.name.length>40||!Number.isInteger(raw.playerCount)||raw.playerCount<5||raw.playerCount>24)throw Error('Bộ đã lưu không hợp lệ.');return {id:raw.id,name:raw.name.trim(),playerCount:raw.playerCount,roles:validRoles(raw.roles,raw.playerCount),settings:validSettings(raw.settings),houseRules:validHouseRules(raw.houseRules),customPool:validPool(raw.customPool)}}
function cleanSavedDecks(raw){if(!Array.isArray(raw))return [];const out=[];for(const item of raw.slice(0,20)){try{const d=validSavedDeck(item);if(!out.some(x=>x.id===d.id))out.push(d)}catch(e){}}return out}
function deckActions(){return `<div class="deck-actions"><button class="secondary" data-action="save-deck">Lưu bộ này</button><button class="text-btn" data-action="saved-decks">Bộ đã lưu (${(state.savedDecks||[]).length})</button></div>`}
function showSaveDeck(){if(configError())return toast('Hoàn thiện bộ vai trước khi lưu: '+configError());if((state.savedDecks||[]).length>=20)return toast('Đã đủ 20 bộ. Xóa một bộ trước khi lưu thêm.');modal.innerHTML=`<div class="dialog-head"><h2>Lưu bộ vai riêng</h2><button class="close" data-action="close" aria-label="Đóng">×</button></div><p>Lưu ${state.players.length} vai, luật nhóm và thiết lập. Tên người chơi và ảnh không nằm trong bộ vai.</p><form id="saveDeckForm"><label class="field"><span>Tên bộ vai</span><input name="deckName" maxlength="40" required placeholder="Ví dụ: Nhóm bạn 12 người"></label><button class="primary" type="submit">Lưu bộ vai</button><p id="deckError" role="alert"></p></form>`;modal.showModal()}
function saveNamedDeck(name){name=String(name||'').trim();state.savedDecks??=[];if(!name||name.length>40)throw Error('Đặt tên từ 1 đến 40 ký tự.');if(state.savedDecks.length>=20)throw Error('Tối đa 20 bộ.');if(state.savedDecks.some(d=>fold(d.name)===fold(name)))throw Error('Tên này đã có. Hãy chọn tên khác.');if(configError())throw Error(configError());const deck=validSavedDeck({id:'d_'+Date.now().toString(36)+'_'+crypto.getRandomValues(new Uint32Array(1))[0].toString(36),name,playerCount:state.players.length,roles:state.roles,settings:state.settings,houseRules:state.houseRules,customPool:state.customPool});state.savedDecks.push(deck);if(!save()){state.savedDecks.pop();throw Error('Chưa lưu được trên thiết bị.')}return deck}
function showSavedDecks(){modal.innerHTML=`<div class="dialog-head"><h2>Bộ vai đã lưu</h2><button class="close" data-action="close" aria-label="Đóng">×</button></div><p>Đang có ${state.players.length} người. Bộ chỉ áp dụng khi khớp số người; tên và ảnh được giữ nguyên.</p><div class="saved-deck-list">${(state.savedDecks||[]).map(d=>`<article><h3>${esc(d.name)}</h3><p>${d.playerCount} người · ${d.settings.mode==='auto'?'Máy dẫn':'Có quản trò'}</p><p>${Object.entries(d.roles).filter(([,n])=>n).map(([k,n])=>esc(ROLES[k].name)+' ×'+n).join(' · ')}</p><div class="actions"><button class="primary" data-action="load-deck" data-id="${d.id}" ${d.playerCount!==state.players.length?'disabled':''}>${d.playerCount===state.players.length?'Dùng bộ này':'Cần '+d.playerCount+' người'}</button><button class="text-btn" data-action="delete-deck" data-id="${d.id}">Xóa bộ</button></div></article>`).join('')||'<p>Chưa có bộ nào. Chỉnh vai rồi bấm Lưu bộ này.</p>'}</div>`;modal.showModal()}
function loadNamedDeck(id){const d=state.savedDecks?.find(d=>d.id===id);if(!d||d.playerCount!==state.players.length)return false;rememberRoleSetup();state.roles=structuredClone(d.roles);state.settings=structuredClone(d.settings);state.houseRules=structuredClone(d.houseRules);state.customPool=[...d.customPool];state.preset='custom';if(needsModerator())state.settings.mode='moderator';save();return true}
function backupObject(){const data=structuredClone(state);data.photos=Array.from({length:data.players.length},(_,i)=>cleanPhoto(data.photos[i]));delete data.setupAdjustment;if(data.game?.mod)data.game.mod.snapshots=[];return {format:'dem-lang-backup',version:1,appVersion:7,exportedAt:new Date().toISOString(),data}}
function downloadBackup(){const blob=new Blob([JSON.stringify(backupObject(),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Ma-Soi-Sao-Luu-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Đã tạo tệp sao lưu. Giữ kín tệp có vai và ảnh.')}
function validateBackup(raw){if(!raw||raw.format!=='dem-lang-backup'||raw.version!==1)throw Error('Không đúng tệp sao lưu Đêm Làng phiên bản 1.');safeTree(raw);const d=raw.data;if(!d||!Array.isArray(d.players)||d.players.length<5||d.players.length>24||d.players.some(n=>typeof n!=='string'||!n.trim()||n.length>28)||new Set(d.players.map(n=>fold(n))).size!==d.players.length)throw Error('Danh sách người chơi không hợp lệ.');const out={...structuredClone(DEFAULT),players:d.players.map(n=>n.normalize('NFC')),roles:validRoles(d.roles,d.players.length,false),settings:validSettings(d.settings),houseRules:validHouseRules(d.houseRules),customPool:validPool(d.customPool),savedDecks:[]};if(!Array.isArray(d.savedDecks)||d.savedDecks.length>20)throw Error('Danh sách bộ đã lưu không hợp lệ.');out.savedDecks=d.savedDecks.map(validSavedDeck);if(new Set(out.savedDecks.map(x=>x.id)).size!==out.savedDecks.length)throw Error('Bộ đã lưu bị trùng mã.');if(!Array.isArray(d.photos)||d.photos.length>24||d.photos.some(p=>typeof p!=='string'||p!==cleanPhoto(p)))throw Error('Ảnh đại diện không hợp lệ.');out.photos=[...d.photos];out.preset=SETUP_PROFILES[d.preset]&&presetAvailable(d.preset,out.players.length)?d.preset:'custom';out.experience=['new','regular','expert'].includes(d.experience)?d.experience:'new';out.game=d.game?validateBackupGame(d.game):null;return out}
function validateBackupGame(raw){const g=structuredClone(raw),stages=['dawn','day','deal','hunter','manual-over','mod-public','moderator','night','over','power','ready','vote'];if(!stages.includes(g.stage)||!Number.isInteger(g.round)||g.round<1||g.round>10000||!Array.isArray(g.players)||g.players.length<5||g.players.length>24)throw Error('Ván chơi không hợp lệ.');g.settings=validSettings(g.settings);
 for(const key of ['bodyguardHits','markRound','arrows','bullets','gunDay','statusIndex'])if(g[key]!==undefined&&(!Number.isInteger(g[key])||g[key]<0||g[key]>10000))throw Error('Tài nguyên kỹ năng không hợp lệ.');
 for(const key of ['healUsed','poisonUsed','hunterUsed','juniorUsed','priestUsed','mayorRevealed'])if(g[key]!==undefined&&typeof g[key]!=='boolean')throw Error('Trạng thái kỹ năng không hợp lệ.');
 if(!Array.isArray(g.publicReport)||g.publicReport.some(x=>typeof x!=='string'||x.length>3000))throw Error('Thông báo không hợp lệ.');
const validId=id=>Number.isInteger(id)&&id>=0&&id<g.players.length;for(let i=0;i<g.players.length;i++){const p=g.players[i];if(p.id!==i||typeof p.name!=='string'||p.name.length>28||!ROLES[p.role]||ROLES[p.role].random||!ROLES[p.initialRole]||ROLES[p.initialRole].random||typeof p.alive!=='boolean'||p.photo!==undefined&&p.photo!==cleanPhoto(p.photo))throw Error('Hồ sơ trong ván không hợp lệ.');for(const key of ['modVotes','modCounter','restRound','readRound'])if(p[key]!==undefined&&(!Number.isInteger(p[key])||p[key]<0||p[key]>10000))throw Error('Điểm người chơi không hợp lệ.');if(p.readResult&&(typeof p.readResult!=='object'||typeof p.readResult.title!=='string'||typeof p.readResult.names!=='string'||p.readResult.title.length>3000||p.readResult.names.length>3000))throw Error('Kết quả điều tra không hợp lệ.');if(p.infos&&!Array.isArray(p.infos)||p.infos?.some(x=>typeof x!=='string'||x.length>3000))throw Error('Sổ kết quả không hợp lệ.');}
 if(g.manual===undefined)g.manual=false;if(typeof g.manual!=='boolean'||!Array.isArray(g.log)||g.log.length>5000||g.log.some(x=>typeof x!=='string'||x.length>3000)||!Array.isArray(g.queue)||g.queue.some(k=>!ROLES[k]&&!['lovers','status'].includes(k))||!Number.isInteger(g.nightIndex)||g.nightIndex<0||g.nightIndex>g.queue.length)throw Error('Lượt chơi không hợp lệ.');for(const key of ['lovers','dawn','hunters'])if(!Array.isArray(g[key])||g[key].some(id=>!validId(id)))throw Error('Danh sách lượt không hợp lệ.');for(const key of ['hunterTarget','juniorTarget','mark','lastGuard'])if(g[key]!=null&&!validId(g[key]))throw Error('Mục tiêu không hợp lệ.');if(!g.night||typeof g.night!=='object'||Array.isArray(g.night))throw Error('Kỹ năng đêm không hợp lệ.');for(const[k,v]of Object.entries(g.night))if(k!=='heal'&&!validId(v)||k==='heal'&&typeof v!=='boolean')throw Error('Mục tiêu kỹ năng không hợp lệ.');for(const key of ['votes','ballots']){if(!g[key]||typeof g[key]!=='object'||Array.isArray(g[key]))throw Error('Phiếu không hợp lệ.');for(const [id,v]of Object.entries(g[key])){if(!validId(Number(id))||key==='votes'&&(!Number.isInteger(v)||v<0||v>100)||key==='ballots'&&v!==''&&(!/^\d+$/.test(String(v))||!validId(Number(v))))throw Error('Phiếu không hợp lệ.')}}if(g.stage==='deal'&&g.dealIndex>=g.players.length||g.stage==='night'&&g.nightIndex>=g.queue.length)throw Error('Vị trí lượt không hợp lệ.');if(!Number.isInteger(g.dealIndex)||g.dealIndex<0||g.dealIndex>g.players.length)throw Error('Chia vai không hợp lệ.');if(![null,'village','wolves','serial','lovers','jester','draw'].includes(g.winner))throw Error('Kết quả không hợp lệ.');if(g.stage==='power'&&!['gunner','priest','marksman','mayor'].includes(g.powerRole))throw Error('Kỹ năng ban ngày không hợp lệ.');if(g.manual){if(!g.mod||!Array.isArray(g.mod.queue)||g.mod.queue.some(k=>!ROLES[k])||!Array.isArray(g.mod.records)||g.mod.records.some(x=>typeof x!=='string')||!Array.isArray(g.mod.pending)||g.mod.pending.some(id=>!validId(id))||!Array.isArray(g.mod.report)||g.mod.report.some(x=>typeof x!=='string')||!Array.isArray(g.mod.winnerIds)||g.mod.winnerIds.some(id=>!validId(id)))throw Error('Bảng quản trò không hợp lệ.');if(!Number.isInteger(g.mod.step)||g.mod.step<0||g.mod.step>g.mod.queue.length||!['night','day'].includes(g.mod.phase)||typeof g.mod.result!=='string'||g.mod.result.length>160)throw Error('Vòng quản trò không hợp lệ.');g.mod.snapshots=[];}ensureGame(g);return g}
function showDataTools(){pendingBackup=null;modal.innerHTML=`<div class="dialog-head"><h2>Sao lưu & khôi phục</h2><button class="close" data-action="close" aria-label="Đóng">×</button></div><p>Tệp JSON gồm người chơi, ảnh, bộ vai riêng và ván đang chơi. Tệp có vai bí mật; chỉ giữ trên thiết bị tin cậy.</p><div class="actions"><button class="primary" data-action="backup-export">Tải tệp sao lưu</button><button class="secondary" data-action="backup-pick">Chọn tệp khôi phục</button></div><input type="file" id="backupFile" accept=".json,application/json" hidden><div id="backupPreview" role="status"></div>`;modal.showModal()}
async function previewBackupFile(file){if(!file)return;if(file.size>8*1024*1024){document.getElementById('backupPreview').textContent='Tệp tối đa 8 MB.';return}try{const raw=JSON.parse(await file.text());pendingBackup=validateBackup(raw);const d=pendingBackup;document.getElementById('backupPreview').innerHTML=`<div class="assist-note"><strong>Đã kiểm tra tệp hợp lệ</strong><p>${d.players.length} người · ${d.photos.filter(Boolean).length} ảnh · ${d.savedDecks.length} bộ riêng · ${d.game?'có ván đang lưu':'không có ván'}</p><p>Khôi phục sẽ thay dữ liệu trên máy. Nên tải bản sao lưu hiện tại trước. Lịch sử hoàn tác không được khôi phục.</p><button class="primary" data-action="backup-restore">Thay dữ liệu bằng bản sao lưu này</button></div>`}catch(e){pendingBackup=null;document.getElementById('backupPreview').textContent='Không nhập tệp: '+e.message}}
function restorePendingBackup(){if(!pendingBackup)return false;const next=pendingBackup;if(Object.entries(next.roles).some(([k,n])=>n>0&&!supportedRole(k)))next.settings.mode='moderator';try{localStorage.setItem('demlang-v1',JSON.stringify(next))}catch(e){toast('Không đủ dung lượng. Dữ liệu hiện tại được giữ nguyên.');return false}stopTimer();stopCamera();state=next;pendingBackup=null;setupUndo=null;secret=false;selected=[];nightResult=null;page='play';return true}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;switch(b.dataset.action){case 'save-deck':showSaveDeck();break;case 'saved-decks':showSavedDecks();break;case 'load-deck':if(loadNamedDeck(b.dataset.id)){modal.close();render();toast('Đã áp dụng bộ vai. Tên và ảnh được giữ nguyên.')}break;case 'delete-deck':{const id=b.dataset.id,d=state.savedDecks.find(x=>x.id===id);if(!d)break;modal.close();confirmBox('Xóa bộ '+esc(d.name)+'?','Bộ đang chọn và ván đang chơi được giữ nguyên.','delete-deck-confirm','Xóa bộ');modal.dataset.deleteDeck=id;break}case 'delete-deck-confirm':{const old=state.savedDecks;state.savedDecks=old.filter(d=>d.id!==modal.dataset.deleteDeck);if(!save())state.savedDecks=old;modal.close();render();break}case 'data-tools':showDataTools();break;case 'backup-export':downloadBackup();break;case 'backup-pick':document.getElementById('backupFile').click();break;case 'backup-restore':if(restorePendingBackup()){modal.close();render();toast('Đã khôi phục dữ liệu. Vai bí mật đang được che.')}break;}});
document.addEventListener('submit',e=>{if(e.target.id!=='saveDeckForm')return;e.preventDefault();try{saveNamedDeck(new FormData(e.target).get('deckName'));modal.close();render();toast('Đã lưu bộ vai riêng.')}catch(err){document.getElementById('deckError').textContent=err.message}});
document.addEventListener('change',e=>{if(e.target.id==='backupFile')previewBackupFile(e.target.files[0])});

document.addEventListener('change', event => {
  if (event.target.id !== 'dealPrivacy') return;
  const button = document.getElementById('dealOpen');
  if (button) button.disabled = !event.target.checked;
});
